/* ============================ CAF Practice Centre engine ============================
 * Vertical slice, phases 5-7: question selection, handwriting transcription,
 * deterministic partial marking, and the mistake book.
 *
 * ------------------------------------------------------------------ honesty note
 * This engine marks from EVIDENCE, not from an answer key, and it is honest about
 * what that means:
 *
 *   - It never awards or withholds a mark on a keyword hit alone. Every criterion
 *     is scored as marks-per-point: a criterion worth N marks over K required
 *     points pays one mark per point demonstrated. A candidate who shows half the
 *     points keeps half the marks. Partial credit is the normal case, not a
 *     fallback.
 *   - Term coverage is ONE evidence channel among several (point coverage,
 *     working structure, causal connectives, conclusion, presentation). A
 *     criterion whose evidence is structural is never decided by string matching.
 *   - If the transcription is missing or the OCR confidence is too low to trust,
 *     the criterion is returned UNREADABLE and contributes ZERO marks, and the
 *     question is flagged. Marks are never invented to fill a gap.
 *   - Practice rubrics are PRACTICE_RUBRIC - shaped from real paper demand, not
 *     an official ICAP marking plan. Official MCQ option letters ARE the
 *     examiner's and are marked exactly.
 *   - Every award carries an audit record (method, matched and missing evidence,
 *     reason code). Nothing is scored silently, so a tutor can see why a mark was
 *     given and override it.
 *   - Client-side only: this is a static page, so it is a first approximation for
 *     self-study, not a secure examination mark. It says so in the result view.
 *
 * Answer keys are never rendered during an attempt. `practiceQuestionView` returns
 * no expected answer; only `practiceFeedback` does, after submission.
 * ============================================================================= */

const PRACTICE_ENGINE_VERSION = "practice-engine/1";

/* ------------------------------------------------------------------ bank index
 * PRACTICE_BANK is emitted by _build/pipeline/build_questionbank.py as positional
 * arrays (see the header of _frag_practice_data.js for the key order). Turning
 * them into objects once, at load, beats re-decoding the shape at every call. */

function practiceIndexBank() {
    if (typeof PRACTICE_BANK === "undefined" || !PRACTICE_BANK) return null;
    if (PRACTICE_BANK._indexed) return PRACTICE_BANK._indexed;

    const generated = (PRACTICE_BANK.generated || []).map(function (r) {
        return {
            kind: "GENERATED_PRACTICE",
            id: r[0], subjectId: r[1], topicId: r[2], text: r[3],
            marks: r[4], minutes: r[5], difficulty: r[6], type: r[7],
            criteria: (r[8] || []).map(function (c) {
                return { id: c[0], maxMarks: c[1], evidence: c[2], errorType: c[3] };
            }),
            evidenceTerms: r[9] || {},
            rubricType: r[10]
        };
    });

    const official = (PRACTICE_BANK.official || []).map(function (r) {
        return {
            kind: "OFFICIAL_PAST_PAPER",
            id: r[0], subjectId: r[1], paperCode: r[2], paperDocId: r[3],
            answerDocId: r[4], questionNumber: r[5], text: r[6], marks: r[7],
            type: r[8],
            criteria: (r[9] || []).map(function (c) {
                return { id: c[0], maxMarks: c[1], evidence: c[2], errorType: c[3] };
            }),
            mcqAnswers: r[10] || {},
            expectedAnswer: r[11] || "",
            rubricType: r[12],
            mcqItems: r[13] || [],
            // Official rows carry term lists as well (slot 14), derived from the
            // ICAP suggested answer they are paired to. Without them the FORMULA
            // criterion on an official numerical question has nothing to match
            // against and scores zero for every answer ever written - the
            // question shows its marks but can never pay them.
            evidenceTerms: r[14] || {},
        };
    });

    /* Full generated papers are a separate payload (`PAPER_BANK`) because they
     * are papers, not questions: each has a total, a Section A the extractor
     * could not recover, a design mix and its own provenance statement. They
     * join `all` - every lookup in this engine resolves a question by id from
     * `all`, and a paper question has to be viewable, markable and summarisable
     * like any other - but they stay OUT of `bySubject`, `byDifficulty` and
     * `byTopic`. Those three indexes are what the setup screen counts with, and
     * folding 124 paper questions in would promise 690 practice questions for a
     * subject that has 566. The counts have to keep meaning what they say. */
    const paperList = (typeof PAPER_BANK !== "undefined" && PAPER_BANK)
        ? (PAPER_BANK.papers || []) : [];
    const paperQuestions = [];
    const paperById = {};
    paperList.forEach(function (p) {
        paperById[p.paperId] = p;
        (p.questions || []).forEach(function (q) {
            paperQuestions.push({
                kind: "GENERATED_PAPER",
                id: q.id, paperId: p.paperId, subjectId: p.subject,
                questionNumber: q.number, section: q.section,
                text: q.text, marks: q.marks, type: q.type,
                criteria: (q.criteria || []).map(function (c) {
                    return {
                        id: c.id, label: c.label, maxMarks: c.maxMarks,
                        evidence: c.evidence, errorType: c.errorType,
                        terms: c.terms || []
                    };
                }),
                expectedAnswer: q.expectedAnswer || "",
                markingNote: q.markingNote || "",
                workings: q.workings || "",
                topicId: q.topicId,
                requirementFromTopic: !!q.requirementFromTopic,
                grounding: {
                    topicId: q.topicId, topicTitle: q.topicTitle,
                    chapter: q.chapter, aligned: !!q.requirementFromTopic
                },
                computation: q.computation || "",
                rubricType: "PRACTICE_RUBRIC"
            });
        });
    });

    const bankPool = generated.concat(official);
    const all = bankPool.concat(paperQuestions);
    const bySubject = {};
    const byDifficulty = {};
    const byTopic = {};
    bankPool.forEach(function (q) {
        (bySubject[q.subjectId] = bySubject[q.subjectId] || []).push(q);
        (byDifficulty[q.difficulty || "OFFICIAL"] = byDifficulty[q.difficulty || "OFFICIAL"] || []).push(q);
        if (q.topicId) byTopic[q.topicId] = q;
    });

    PRACTICE_BANK._indexed = {
        all: all, generated: generated, official: official,
        paperQuestions: paperQuestions, paperById: paperById, paperList: paperList,
        bySubject: bySubject, byDifficulty: byDifficulty, byTopic: byTopic,
        sourceLabel: PRACTICE_BANK.sourceLabel
    };
    return PRACTICE_BANK._indexed;
}

/* One paper question as the engine sees it. Kept beside the index so the id
 * namespace (`pp-<paperId>-q<n>`, asserted disjoint from the bank's in
 * build_paper_layer.py) has a single definition. */
function practicePaperQuestion(paperId, question) {
    const bank = practiceIndexBank();
    if (!bank) return null;
    const id = question ? question.id : null;
    return bank.all.filter(function (x) { return x.id === id && x.paperId === paperId; })[0] || null;
}

function practicePaperById(paperId) {
    const bank = practiceIndexBank();
    if (!bank) return null;
    return bank.paperById[paperId] || null;
}

/* ------------------------------------------------------- expected-answer lookup
 * The study text is already in this file as mmDataStore, so the expected answer is
 * resolved from it on demand rather than stored twice. See emit_runtime_fragment()
 * in the builder for why. */

function practiceStudyTopic(topicId) {
    if (typeof mmDataStore === "undefined" || !mmDataStore || !topicId) return null;
    for (const subjectId in mmDataStore) {
        if (!Object.prototype.hasOwnProperty.call(mmDataStore, subjectId)) continue;
        const chapters = mmDataStore[subjectId] || [];
        for (let i = 0; i < chapters.length; i++) {
            const topics = (chapters[i] && chapters[i].topics) || [];
            for (let j = 0; j < topics.length; j++) {
                if (topics[j] && topics[j].id === topicId) {
                    return {
                        subjectId: subjectId,
                        chapterTitle: chapters[i].title,
                        chapterNumber: chapters[i].chapterNumber,
                        title: topics[j].title,
                        kind: topics[j].kind,
                        keyPoints: topics[j].keyPoints || [],
                        formula: topics[j].formula || "",
                        examTip: topics[j].examTip || "",
                        studyPage: topics[j].studyPage
                    };
                }
            }
        }
    }
    return null;
}

function practiceExpectedAnswer(question) {
    if (!question) return "";
    if (question.expectedAnswer) return question.expectedAnswer;
    /* A paper question stops here. Its own suggested answer may be empty -
     * SCENARIO and RECALL papers ship a marking note instead of an answer - and
     * falling through to `practiceStudyTopic` would quote the topic the question
     * was FILED under, which is not the same thing: caf1-gen-1's depreciation
     * question sits under "Not for Profit Organisations". Quoting it as the
     * expected answer would be a confident, wrong citation. */
    if (question.kind === "GENERATED_PAPER") return "";
    const topic = practiceStudyTopic(question.topicId);
    if (!topic) return "";
    const parts = [];
    if (topic.formula) parts.push("Formula: " + topic.formula);
    (topic.keyPoints || []).forEach(function (k) {
        if (typeof k === "string" && k.trim()) parts.push(k.trim());
    });
    return parts.join(" ").replace(/\s+/g, " ");
}

/* ============================================================ handwriting OCR
 * The spec forbids faking OCR, so there is no built-in "pretend" recogniser.
 * `setOCRProvider` / `getOCRProvider` wrap a real adapter that POSTs the image to an endpoint
 * the user supplies with their own key. A `manual` provider is also registered:
 * that is the student typing their answer, which is honest - it is labelled
 * MANUAL and is not presented as handwriting recognition.
 *
 * Configure with:
 *   setOCRProvider({ adapter: "rest", endpoint: "...", apiKey: "...",
 *                    fieldName: "image", responsePath: "data.text" })
 */

const OCR_MIN_CONFIDENCE = 0.55;

const OCR_ADAPTERS = {
    /* Generic JSON-over-HTTP adapter. `responsePath` is a dotted path into the
     * provider's JSON reply, so a specific vendor can be supported by config
     * alone rather than by writing another adapter. */
    rest: {
        name: "rest",
        describe: function (cfg) {
            return "HTTP OCR via " + (cfg.endpoint || "(no endpoint set)");
        },
        available: function (cfg) {
            return !!(cfg && cfg.endpoint);
        },
        transcribe: function (cfg, imageDataUrl) {
            const field = cfg.fieldName || "image";
            const body = {};
            body[field] = imageDataUrl;
            if (cfg.apiKey) body[cfg.apiKeyField || "key"] = cfg.apiKey;
            if (cfg.extraFields) {
                for (const k in cfg.extraFields) {
                    if (Object.prototype.hasOwnProperty.call(cfg.extraFields, k)) body[k] = cfg.extraFields[k];
                }
            }
            return fetch(cfg.endpoint, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(body)
            }).then(function (res) {
                if (!res.ok) throw new Error("OCR endpoint returned HTTP " + res.status);
                return res.json();
            }).then(function (json) {
                const picked = practicePickPath(json, cfg.responsePath || "text");
                if (picked == null) throw new Error("OCR response did not contain " + (cfg.responsePath || "text"));
                return {
                    text: String(picked),
                    confidence: practicePickPath(json, cfg.confidencePath || "confidence"),
                    provider: cfg.name || "rest",
                    raw: json
                };
            });
        }
    },

    manual: {
        name: "manual",
        describe: function () { return "Typed answer (no handwriting recognition)"; },
        available: function () { return true; },
        transcribe: function (cfg, imageDataUrl) {
            return Promise.resolve({
                text: (cfg && cfg.typedText) || "",
                confidence: 1,
                provider: "manual",
                manual: true
            });
        }
    }
};

let OCR_ACTIVE = { adapter: "manual", config: {} };

function setOCRProvider(cfg) {
    OCR_ACTIVE = {
        adapter: (cfg && cfg.adapter) || "manual",
        config: cfg || {},
        name: (cfg && cfg.name) || (cfg && cfg.adapter) || "manual"
    };
    return OCR_ACTIVE;
}

function getOCRProvider() {
    const adapter = OCR_ADAPTERS[OCR_ACTIVE.adapter];
    if (!adapter) throw new Error("Unknown OCR adapter: " + OCR_ACTIVE.adapter);
    return {
        name: OCR_ACTIVE.name,
        adapter: adapter,
        /* `describe` is a function, matching `transcribe`. Returning the already-
         * formatted string here instead made every caller that reached for
         * provider.describe() throw "not a function". */
        describe: function () { return adapter.describe(OCR_ACTIVE.config); },
        available: adapter.available(OCR_ACTIVE.config),
        transcribe: function (imageDataUrl) {
            return adapter.transcribe(OCR_ACTIVE.config, imageDataUrl);
        }
    };
}

function practicePickPath(obj, path) {
    if (!path) return obj;
    const parts = String(path).split(".");
    let cur = obj;
    for (let i = 0; i < parts.length; i++) {
        if (cur == null) return null;
        const key = parts[i];
        if (Array.isArray(cur)) cur = cur[Number(key)];
        else cur = cur[key];
    }
    return cur;
}

/* Transcribe and normalise. A confidence we cannot interpret is treated as
 * unknown, not as zero, so a provider that omits the field is not silently
 * failed - but an unreadable result still blocks marking rather than guessing. */
function transcribeAnswer(imageDataUrl) {
    const provider = getOCRProvider();
    return provider.transcribe(imageDataUrl).then(function (res) {
        const raw = res.confidence;
        const conf = (typeof raw === "number" && isFinite(raw))
            ? (raw > 1 ? raw / 100 : raw)
            : null;
        return {
            text: practiceNormalize(res.text || ""),
            rawText: res.text || "",
            confidence: conf,
            provider: res.provider || provider.name,
            manual: !!res.manual,
            lowConfidence: conf === null ? false : conf < OCR_MIN_CONFIDENCE,
            empty: !(res.text || "").trim()
        };
    });
}

/* ============================================================== text handling */

const PRACTICE_STOPWORDS = ("a an the and or of for to in on at by with from is are was " +
    "were be been being has have had do does did will would shall should may might must " +
    "can could this that these those it its as if then than so such not no nor but per " +
    "into over under about after before also more most other some any all each both which " +
    "who whom whose what when where why how there their them they he she his her him").split(/\s+/);

function practiceNormalize(text) {
    return String(text || "")
        .replace(/\r/g, "\n")
        .replace(/[‐-―−]/g, "-")
        .replace(/[‘’‛]/g, "'")
        .replace(/[“”]/g, '"')
        .replace(/[ \t]+/g, " ")
        .replace(/\n{3,}/g, "\n\n")
        .trim();
}

function practiceTokens(text) {
    const out = [];
    const seen = Object.create(null);
    const words = String(text || "").toLowerCase().match(/[a-z][a-z\-']{2,}/g) || [];
    for (let i = 0; i < words.length; i++) {
        const w = words[i];
        if (PRACTICE_STOPWORDS.indexOf(w) !== -1) continue;
        if (seen[w]) continue;
        seen[w] = 1;
        out.push(w);
    }
    return out;
}

/* OCR routinely turns rn into m, 0 into O, 1 into l. Matching on the raw string
 * would fail a correct answer for a mechanical reason, so both sides are folded
 * to a comparison form. This widens a match; it never narrows one, so it cannot
 * manufacture credit that a clean transcription would not have earned. */
function practiceFoldForMatch(text) {
    return String(text || "")
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "");
}

const PRACTICE_NUMBER_RE = /-?\d[\d,]*(?:\.\d+)?/g;
const PRACTICE_OP_RE = /(?:[=+\-*/x×]\s*\d|\d\s*(?:=|x|×)\s*\d|\d\s*[-+]\s*\d|rs\.?\s*\d|\d\s*%)/i;
const PRACTICE_CAUSAL_RE = /\b(because|therefore|thus|hence|since|as a result|consequently|due to|so that|leads? to|results? in|owing to|reason(?:s)? for|which means|it follows)\b/i;
const PRACTICE_CONCLUDE_RE = /\b(therefore|in conclusion|conclusion|to conclude|advise|recommend|we can (?:conclude|say)|thus it (?:is|follows)|finally|overall)\b/i;
/* Global on purpose. This one is counted with `.match(...).length`, and a
 * non-global regex returns [first match, capture group] instead of every match:
 * `(^|\n)` guarantees a capture group, so "bullets" came back as exactly 2 for
 * ANY answer with a bullet in it and 0 for any answer without one. Full credit
 * (`bullets >= 3`) was therefore unreachable, and the 2-bullet tier was the
 * only tier that could ever fire - so every presentation criterion in the bank
 * was capped at 0.6 of its marks and nobody saw a failure, just slightly mean
 * marks. The causal and conclude regexes are counted the same way and are
 * copied per call with `new RegExp(..., "gi")` instead; this one has one caller,
 * so it carries the flag. */
const PRACTICE_STRUCTURE_RE = /(^|\n)\s*(?:[0-9]{1,2}[.)]\s|[-*•]\s|[A-Z][.)]\s|#{1,4}\s)|(?:^|\n)\s*[A-Z][A-Za-z ]{2,28}:\s*$|\|.*\|/g;

/* ============================================================== the marker */

const PRACTICE_REASON = {
    FULL: "FULL_CREDIT",
    PARTIAL: "PARTIAL_CREDIT",
    NONE: "NO_EVIDENCE",
    UNREADABLE: "TRANSCRIPTION_UNREADABLE",
    WRONG_OPTION: "WRONG_OPTION_SELECTED",
    CORRECT_OPTION: "CORRECT_OPTION_SELECTED"
};

/* Marks per point.
 *
 * This allocates a FRACTIONAL mark value to each piece of evidence, so the
 * criterion grades continuously. Integer marks-per-point looks more like a real
 * mark scheme but degenerates badly here: a 5-mark criterion carrying 8 evidence
 * terms gives floor(5/8) = 0 marks to the first three, so hitting 5 of 8
 * collected every mark and the criterion silently stopped being partial credit.
 * A candidate could answer half and be told they were right - which is the exact
 * failure the partial-marks requirement exists to prevent.
 *
 * Fractional allocation means full marks require every piece of evidence, and
 * any prefix of it earns a proportional share.
 */
function practicePointBudget(maxMarks, pointCount) {
    if (pointCount <= 0) return [];
    const each = maxMarks / pointCount;
    const out = new Array(pointCount);
    for (let i = 0; i < pointCount; i++) out[i] = each;
    return out;
}

function practiceScorePoints(maxMarks, terms, foldHaystack, rawHaystack) {
    const budget = practicePointBudget(maxMarks, terms.length);
    const matched = [];
    const missing = [];
    let running = 0;

    for (let i = 0; i < terms.length; i++) {
        const term = terms[i];
        const needle = practiceFoldForMatch(term);
        // long enough to be specific; a 3-letter fragment would match noise
        const hit = needle.length >= 4 && foldHaystack.indexOf(needle) !== -1;
        if (hit) {
            running += budget[i];
            matched.push(term);
        } else {
            missing.push(term);
        }
    }
    return {
        awarded: Math.min(maxMarks, running),
        matched: matched,
        missing: missing,
        pointMarks: terms.map(function (t, i) {
            return matched.indexOf(t) === -1 ? 0 : budget[i];
        }),
        rawUsed: rawHaystack
    };
}

/* Structural criteria: does the answer behave like the thing being assessed? These
 * never consult term lists, so a candidate cannot pass them by parroting. */
function practiceScoreWorking(maxMarks, rawText) {
    const lines = String(rawText).split(/\n+/).map(function (l) { return l.trim(); })
        .filter(function (l) { return l.length > 0; });
    let workingLines = 0;
    let hasFinal = false;
    for (let i = 0; i < lines.length; i++) {
        const nums = lines[i].match(PRACTICE_NUMBER_RE);
        if (nums && nums.length >= 2 && PRACTICE_OP_RE.test(lines[i])) workingLines++;
        if (PRACTICE_OP_RE.test(lines[i]) && nums) hasFinal = true;
    }
    // One line of arithmetic is the minimum credit; three or more is full marks.
    let ratio = 0;
    if (workingLines >= 3) ratio = 1;
    else if (workingLines === 2) ratio = 0.67;
    else if (workingLines === 1) ratio = 0.34;
    // A concluding figure: one written after an equals sign, after an answer
    // word ("total 48,500"), or after "Rs.". The `=` used to sit inside a `\b`
    // alternation, where it can never match - a word boundary either side of a
    // non-word character does not exist - so "charge = 67,500" was read as an
    // answer with no figure in it, the bonus never fired, and the candidate was
    // told the answer had "no concluding figure stated".
    const hasAnswerFigure =
        /(?:[=:]\s*-?\d[\d,]*(?:\.\d+)?|\b(?:answer|total|therefore|thus)\b[^0-9]{0,12}-?\d[\d,]*(?:\.\d+)?|\bRs\.?\s*\d[\d,]*(?:\.\d+)?)/i
            .test(rawText);
    let awarded = ratio * maxMarks;
    if (hasFinal && hasAnswerFigure) awarded = Math.min(maxMarks, awarded + maxMarks * 0.2);
    return {
        awarded: Math.min(maxMarks, Math.round(awarded * 100) / 100),
        matched: [workingLines + " arithmetic line(s)"],
        missing: hasAnswerFigure ? [] : ["no concluding figure stated"],
        pointMarks: []
    };
}

function practiceScoreCausal(maxMarks, rawText) {
    const hits = String(rawText).match(new RegExp(PRACTICE_CAUSAL_RE, "gi")) || [];
    const n = hits.length;
    const ratio = n >= 2 ? 1 : (n === 1 ? 0.5 : 0);
    return {
        awarded: maxMarks * ratio,
        matched: hits.slice(0, 6),
        missing: n ? [] : ["no causal connective used"],
        pointMarks: []
    };
}

function practiceScoreConclusion(maxMarks, rawText) {
    const m = String(rawText).match(new RegExp(PRACTICE_CONCLUDE_RE, "gi")) || [];
    const ratio = m.length >= 1 ? 1 : 0;
    return {
        awarded: maxMarks * ratio,
        matched: m.slice(0, 4),
        missing: ratio ? [] : ["no conclusion stated"],
        pointMarks: []
    };
}

function practiceScoreStructure(maxMarks, rawText) {
    const lines = String(rawText).split(/\n+/).filter(function (l) { return l.trim().length; });
    const bullets = (String(rawText).match(PRACTICE_STRUCTURE_RE) || []).length;
    const words = String(rawText).trim().split(/\s+/).filter(Boolean).length;
    // Structure is judged on legible organisation, not on being long: a tidy
    // five-line answer outscores a dense unreadable paragraph, and neither is
    // rewarded for padding.
    let ratio = 0;
    if (bullets >= 3) ratio = 1;
    else if (bullets === 2) ratio = 0.6;
    else if (bullets === 1) ratio = 0.3;
    else if (lines.length >= 4 && words >= 60) ratio = 0.4;
    else if (words >= 25) ratio = 0.15;
    return {
        awarded: maxMarks * ratio,
        matched: bullets ? [bullets + " structured line(s)"] : [lines.length + " line(s)"],
        missing: ratio >= 1 ? [] : ["answer not laid out in a readable structure"],
        pointMarks: []
    };
}

function practiceScoreAdjustment(maxMarks, terms, rawText, foldHaystack) {
    const base = practiceScorePoints(maxMarks, terms, foldHaystack, rawText);
    const says = /\b(adjust\w*|correct\w*|revis\w*|overstat\w*|understat\w*|err(or|one)|omitt\w*)\b/i.test(rawText);
    /* NOT `PRACTICE_NUMBER_RE.test(rawText)`. That regex is global so that
     * `.match()` returns every figure, and `.test()` on a global regex is
     * stateful: it starts at lastIndex, advances it on a hit, and carries that
     * position into the next call. The first adjustment criterion marked in a
     * session got the quantification bonus and later ones silently did not,
     * because by then lastIndex sat past the figure in their answer. A match
     * resets the index and answers the same question. */
    const quantified = String(rawText).match(PRACTICE_NUMBER_RE) !== null;
    if (base.awarded === 0 && (says || quantified)) {
        // Recognised that something needs changing but never named the point.
        return {
            awarded: maxMarks * 0.25,
            matched: base.matched.concat(says ? ["adjustment implied"] : []),
            missing: base.missing,
            pointMarks: []
        };
    }
    if (base.awarded > 0 && quantified) {
        base.awarded = Math.min(maxMarks, base.awarded + maxMarks * 0.15);
        base.matched = base.matched.concat(["adjustment quantified"]);
    }
    return base;
}

/* The facts a candidate is expected to engage: the paper's own entity and the
 * figures it states. This is the evidence channel for "Applies it to the
 * specific facts stated, not in general terms" - a criterion worth up to 5
 * marks in every SCENARIO question, and one no word list drawn from the
 * criterion itself could judge, because that criterion names no content at all.
 *
 * Reading the answer for the question's own facts is what "applies it to the
 * facts" means. It is evidence from the paper, not from an answer key: these
 * papers carry no suggested answer for SCENARIO questions, only the rubric.
 */
function practiceQuestionAnchors(text) {
    const t = String(text || "");
    const out = [];
    const seen = {};
    function push(kind, raw) {
        if (out.length >= 5) return;
        const key = kind + ":" + raw;
        if (seen[key]) return;
        seen[key] = 1;
        out.push({ kind: kind, raw: raw });
    }

    /* Figures first, and only figures if the paper states any: the specific
     * facts in a scenario question are its numbers ("borrowing costs of
     * Rs. 220,000", "net assets of Rs. 80,000"), and an answer applying the
     * rule to those facts restates them. Four digits or more, and not a year -
     * "year ended 31 December 2026" is context, not a fact an answer has to
     * quote, and requiring it would cost every candidate a mark for nothing. */
    const nums = t.match(/\b\d[\d,]{3,}\b/g) || [];
    nums.forEach(function (n) {
        const digits = n.replace(/[^0-9]/g, "").replace(/^0+(?=\d)/, "");
        if (digits.length < 4) return;
        if (digits.length === 4 && +digits >= 1900 && +digits <= 2100) return;
        push("figure", digits);
    });

    /* Entity codes only where there are no figures to read. The stems write
     * "Thornbury Textiles (TL)", but a candidate who answers "the company" has
     * still applied the rule to the facts, so the code is a fallback signal
     * rather than a requirement. */
    if (!out.length) {
        const codes = t.match(/\(([A-Z]{2,4})\)/g) || [];
        codes.forEach(function (c) { push("entity", c.replace(/[()]/g, "")); });
    }
    return out;
}

function practiceScoreAppliedFacts(maxMarks, anchors, rawText) {
    if (!anchors || !anchors.length) {
        // Nothing to anchor on. Judge the answer on its organisation rather
        // than awarding zero for a criterion the paper gave us no facts to read.
        return practiceScoreStructure(maxMarks, rawText);
    }
    const ans = String(rawText || "");
    // Non-digits collapse to a SPACE, not to nothing. Stripping them outright
    // glues every figure in the answer into one run of digits, after which
    // "220,000" sits between two neighbours that are digits and the boundary
    // test below rejects it: a correct answer scored 0/3 on the one criterion
    // that was supposed to reward it. Thousands separators are removed first,
    // or the comma would split its own figure in half (220,000 -> "220 000").
    const digits = ans.replace(/(\d),(?=\d)/g, "$1").replace(/[^0-9]+/g, " ");
    const matched = [];
    const missing = [];
    anchors.forEach(function (a) {
        let hit = false;
        if (a.kind === "entity") {
            hit = new RegExp("\\b" + a.raw + "\\b").test(ans);
        } else {
            // Figures are compared digit-for-digit with non-digit boundaries on
            // both sides, so 220,000 is not credited by an answer that says
            // 1,220,000 and 50,000 is not credited by 150,000.
            let at = digits.indexOf(a.raw);
            while (at !== -1) {
                const before = at > 0 ? digits.charAt(at - 1) : "";
                const after = digits.charAt(at + a.raw.length);
                if (!/[0-9]/.test(before) && !/[0-9]/.test(after)) { hit = true; break; }
                at = digits.indexOf(a.raw, at + 1);
            }
        }
        if (hit) matched.push(a.raw); else missing.push(a.raw);
    });
    const ratio = matched.length / anchors.length;
    return {
        awarded: Math.round(maxMarks * ratio * 100) / 100,
        matched: matched,
        missing: missing,
        pointMarks: []
    };
}

/* One criterion -> one awarded figure, one status, one audit record. */
function practiceScoreCriterion(criterion, ctx) {
    const maxMarks = criterion.maxMarks || 0;
    const audit = {
        criterionId: criterion.id,
        label: criterion.label || criterion.id,
        maxMarks: maxMarks,
        evidence: criterion.evidence,
        errorType: criterion.errorType,
        awarded: 0,
        status: PRACTICE_REASON.NONE,
        matched: [],
        missing: []
    };

    if (maxMarks <= 0) return audit;

    // An unreadable transcription earns nothing and is declared, rather than
    // being scored against evidence that was never captured.
    if (ctx.unreadable) {
        audit.awarded = 0;
        audit.status = PRACTICE_REASON.UNREADABLE;
        audit.note = ctx.unreadableReason || "transcription unavailable";
        return audit;
    }

    let res;
    switch (criterion.evidence) {
        case "numericLines":
            res = practiceScoreWorking(maxMarks, ctx.rawText);
            break;
        case "appliedFacts":
            res = practiceScoreAppliedFacts(maxMarks, ctx.anchors, ctx.rawText);
            break;
        case "reasonTerms":
            res = practiceScoreCausal(maxMarks, ctx.rawText);
            break;
        case "concludeTerms":
            res = practiceScoreConclusion(maxMarks, ctx.rawText);
            break;
        case "structureTerms":
            res = practiceScoreStructure(maxMarks, ctx.rawText);
            break;
        case "adjustTerms":
            res = practiceScoreAdjustment(
                maxMarks, ctx.termsFor(criterion.id) || ["adjust", "correction", "error"],
                ctx.rawText, ctx.fold);
            break;
        case "formulaTerms":
        case "keyPointTerms":
        default: {
            const terms = ctx.termsFor(criterion.id) || [];
            if (!terms.length) {
                // No evidence list means we cannot judge it. Say so instead of
                // awarding a mark we cannot justify.
                audit.awarded = 0;
                audit.status = PRACTICE_REASON.NONE;
                audit.note = "no evidence list recorded for this criterion";
                return audit;
            }
            res = practiceScorePoints(maxMarks, terms, ctx.fold, ctx.rawText);
            break;
        }
    }

    audit.awarded = Math.round(Math.min(maxMarks, Math.max(0, res.awarded)) * 100) / 100;
    audit.matched = res.matched || [];
    audit.missing = res.missing || [];
    if (audit.awarded >= maxMarks) audit.status = PRACTICE_REASON.FULL;
    else if (audit.awarded > 0) audit.status = PRACTICE_REASON.PARTIAL;
    else audit.status = PRACTICE_REASON.NONE;
    return audit;
}

/* MCQ: the examiner's letters are official, so this is an exact comparison and
 * gets no partial credit - there is nothing between right and wrong here. */
function practiceMarkMCQ(question, selected) {
    const official = question.mcqAnswers || {};
    const keys = Object.keys(official);
    if (!keys.length) return null;
    // `selected` is a map of item -> chosen option letter, so the lookup has to
    // be per item. Stringifying the whole map compares the answer sheet against
    // itself and marks a fully correct set as 0.
    const picks = selected || {};
    const rows = keys.map(function (k) {
        const raw = picks[k];
        const chosen = (raw === undefined || raw === null || raw === "") ? null
            : String(raw).trim().toLowerCase();
        const correct = official[k].toLowerCase();
        const isRight = chosen === correct;
        return {
            item: k,
            correctOption: correct,
            selectedOption: chosen,
            outcome: chosen === null ? "NOT_ANSWERED"
                : (isRight ? PRACTICE_REASON.CORRECT_OPTION : PRACTICE_REASON.WRONG_OPTION)
        };
    });
    const right = rows.filter(function (r) { return r.outcome === PRACTICE_REASON.CORRECT_OPTION; }).length;
    const total = question.marks || keys.length;
    const awarded = total * (right / keys.length);
    return {
        awarded: Math.round(awarded * 100) / 100,
        maxMarks: total,
        right: right,
        itemCount: keys.length,
        rows: rows,
        status: right === keys.length ? PRACTICE_REASON.FULL
            : (right > 0 ? PRACTICE_REASON.PARTIAL : PRACTICE_REASON.NONE)
    };
}

/* Mark one question. Returns the award plus the full audit trail. */
function practiceMarkQuestion(question, transcription) {
    const result = {
        questionId: question.id,
        kind: question.kind,
        marks: question.marks,
        rubricType: question.rubricType,
        criteria: [],
        awarded: 0,
        maxMarks: question.marks,
        unreadable: false,
        warnings: []
    };

    if (!question) return result;

    // --- objective: exact comparison against the examiner's own letters -------
    if (question.kind === "OFFICIAL_PAST_PAPER" && question.mcqAnswers
            && Object.keys(question.mcqAnswers).length) {
        const mcq = practiceMarkMCQ(question, transcription && transcription.selectedOptions);
        if (mcq) {
            result.mcq = mcq;
            result.awarded = mcq.awarded;
            result.status = mcq.status;
            return result;
        }
    }

    const rawText = (transcription && transcription.rawText) || transcription.text || "";
    const conf = transcription ? transcription.confidence : null;

    // --- can we honestly read this at all? ---------------------------------
    let unreadableReason = null;
    if (!rawText || !rawText.trim()) {
        unreadableReason = "no readable text was captured";
    } else if (transcription && transcription.lowConfidence) {
        unreadableReason = "transcription confidence " +
            (conf === null ? "unknown" : Math.round(conf * 100) + "%") + " is below the "
            + Math.round(OCR_MIN_CONFIDENCE * 100) + "% floor";
    }
    result.unreadable = !!unreadableReason;

    // Evidence terms live in one of two places, and both have to be read: the
    // practice bank keeps a per-question map keyed by criterion id, while a
    // paper question carries its terms on the criterion itself, built from the
    // criterion's own wording and the requirement material its stem prints.
    const termsById = {};
    (question.criteria || []).forEach(function (c) {
        if (c.terms && c.terms.length) termsById[c.id] = c.terms;
    });
    Object.keys(question.evidenceTerms || {}).forEach(function (k) {
        if (!termsById[k]) termsById[k] = question.evidenceTerms[k];
    });

    const ctx = {
        rawText: rawText,
        fold: practiceFoldForMatch(rawText),
        // The facts this question states - the evidence for `appliedFacts`.
        anchors: practiceQuestionAnchors(question.text),
        unreadable: result.unreadable,
        unreadableReason: unreadableReason,
        termsFor: function (criterionId) {
            return termsById[criterionId] || [];
        }
    };

    let awarded = 0;
    (question.criteria || []).forEach(function (c) {
        const audit = practiceScoreCriterion(c, ctx);
        result.criteria.push(audit);
        if (audit.awarded > 0) awarded += audit.awarded;
    });

    // A criterion marked UNREADABLE blocks the whole question from claiming a
    // clean result - the student is told to retype rather than shown a low score
    // that reads like a wrong answer.
    if (result.unreadable) {
        result.awarded = 0;
        result.status = PRACTICE_REASON.UNREADABLE;
        result.note = unreadableReason;
    } else {
        result.awarded = Math.round(Math.min(question.marks, awarded) * 100) / 100;
        const pct = question.marks ? result.awarded / question.marks : 0;
        result.status = pct >= 0.999 ? PRACTICE_REASON.FULL
            : (pct > 0 ? PRACTICE_REASON.PARTIAL : PRACTICE_REASON.NONE);
    }

    result.percent = question.marks ? Math.round(result.awarded / question.marks * 100) : 0;
    // Read from the AUDIT records, not from the rubric. The rubric entries have
    // no `awarded` field, so filtering on them compares undefined against a
    // number, is always false, and silently empties the mistake book.
    result.errorsLost = result.criteria.filter(function (c) {
        return c.awarded < c.maxMarks;
    }).map(function (c) {
        return {
            errorType: c.errorType,
            criterionId: c.criterionId,
            marksLost: Math.round((c.maxMarks - c.awarded) * 100) / 100,
            missingEvidence: c.missing || [],
            matchedEvidence: c.matched || []
        };
    });
    return result;
}

/* ================================================================ the session */

/* The chapter a question belongs to.
 *
 * The runtime bank row carries `topicId` and not `chapterId`, so the chapter is
 * derived: a topic id is always `<subject>-ch<N>-t<M>`. Every one of the 689
 * generated questions matches that shape; the 61 official past-paper questions
 * carry no topicId at all, which is why the chapter control is disabled for
 * that source rather than quietly returning nothing. */
function practiceChapterId(question) {
    if (!question) return "";
    if (question.chapterId) return question.chapterId;
    const m = String(question.topicId || "").match(/^(.*)-t\d+$/);
    return m ? m[1] : "";
}

/* Every question a set of options can reach, in draw order.
 *
 * Split out of `practiceSelectQuestions` so the setup screen counts the SAME
 * pool the session is drawn from. When these were one function the count beside
 * a subject came from `bySubject` while the draw used a focus filter, and the
 * two could not both be right. */
function practiceSelectPool(opts) {
    const o = opts || {};
    const bank = practiceIndexBank();
    if (!bank) return [];
    let pool = o.kind === "OFFICIAL_PAST_PAPER" ? bank.official : bank.generated;
    if (o.subjectId) {
        /* Resolve the subject through its row so `caf4v1` reaches the bank's
         * `caf4` questions. Comparing `q.subjectId === o.subjectId` matched
         * nothing for Business Law Vol 1, so a subject the dropdown had just
         * offered came back as "nothing selected". */
        const row = (typeof practiceCentreSubjectFor === "function")
            ? practiceCentreSubjectFor(o.subjectId) : null;
        const want = row ? row.bankIds : [o.subjectId];
        pool = pool.filter(function (q) { return want.indexOf(q.subjectId) !== -1; });
    }
    if (o.difficulty) {
        pool = pool.filter(function (q) { return q.difficulty === o.difficulty; });
    }
    if (o.type) {
        pool = pool.filter(function (q) { return q.type === o.type; });
    }
    /* A focus source narrows the pool to the subjects and question types it
     * names. Read from `kind` rather than passed as a separate option, so every
     * caller - the setup form, "where am I weak?", a restored session - gets the
     * same narrowing by construction rather than by remembering to pass it. */
    const focus = (typeof practiceCentreFocusById === "function")
        ? practiceCentreFocusById(o.kind) : null;
    if (focus) {
        const want = {};
        focus.subjects.forEach(function (s) {
            const r = practiceCentreSubjectFor(s);
            (r ? r.bankIds : [s]).forEach(function (b) { want[b] = true; });
        });
        pool = pool.filter(function (q) {
            return !!want[q.subjectId] && focus.types.indexOf(q.type) !== -1;
        });
    }
    /* A chapter narrows further. Applied after the focus filter, so a chapter
     * inside a focus source yields that chapter's focus questions and not the
     * subject's whole set. */
    if (o.chapterId) {
        pool = pool.filter(function (q) { return practiceChapterId(q) === o.chapterId; });
    }
    // Weighted draw: study-time-appropriate questions first, but with genuine
    // variety so a session is not five definition questions in a row.
    const order = { FOUNDATION: 0, APPLICATION: 1, ADVANCED: 2, EXAM_LEVEL: 3 };
    pool = pool.slice().sort(function (a, b) {
        const d = (order[a.difficulty] === undefined ? 9 : order[a.difficulty])
            - (order[b.difficulty] === undefined ? 9 : order[b.difficulty]);
        if (d) return d;
        return a.marks - b.marks;
    });

    /* A focus source naming more than one type has to actually deliver more than
     * one type. The sort above orders by marks, and every numerical question is
     * shorter than every scenario one - so "numerical and scenario" drew five
     * numericals while its own note promised a mix. Weave the types together
     * once the difficulty order is fixed, so variety does not become a session
     * of five computations that differ only in their figures.
     *
     * Interleaved by type only; within a type the difficulty order stands. */
    if (focus && focus.types.length > 1) {
        const buckets = {};
        focus.types.forEach(function (t) { buckets[t] = []; });
        const rest = [];
        pool.forEach(function (q) {
            if (buckets[q.type]) buckets[q.type].push(q);
            else rest.push(q);
        });
        const longest = focus.types.reduce(function (m, t) {
            return Math.max(m, buckets[t].length);
        }, 0);
        const woven = [];
        for (let i = 0; i < longest; i++) {
            focus.types.forEach(function (t) {
                if (buckets[t][i]) woven.push(buckets[t][i]);
            });
        }
        woven.push.apply(woven, rest);
        pool = woven;
    }
    return pool;
}

function practiceSelectQuestions(opts) {
    const o = opts || {};
    const pool = practiceSelectPool(o);
    if (!pool.length && !practiceIndexBank()) return [];

    const want = o.count || 10;
    const out = [];
    const usedTopic = {};
    for (let pass = 0; pass < 3 && out.length < want; pass++) {
        for (let i = 0; i < pool.length && out.length < want; i++) {
            const q = pool[i];
            if (out.indexOf(q) !== -1) continue;
            if (pass > 0 && usedTopic[q.topicId || q.id]) continue;
            usedTopic[q.topicId || q.id] = 1;
            out.push(q);
        }
    }
    return out;
}

function practiceCreateSession(opts) {
    const o = opts || {};
    const questions = o.questions || practiceSelectQuestions(o);
    return {
        version: PRACTICE_ENGINE_VERSION,
        sessionId: "ps-" + Date.now().toString(36),
        subjectId: o.subjectId || null,
        label: o.label || "Practice session",
        mode: o.kind === "OFFICIAL_PAST_PAPER" ? "PAST_PAPER"
            : (o.kind === "GENERATED_PAPER" ? "GENERATED_PAPER" : "GENERATED_PRACTICE"),
        // Which paper a GENERATED_PAPER session is sitting, so the summary and
        // anything exported from it can name the paper rather than infer it
        // from the first question's id.
        paperId: o.paperId || null,
        startedAt: new Date().toISOString(),
        finishedAt: null,
        ocrProvider: getOCRProvider().name,
        questions: questions.map(function (q) {
            return { id: q.id, marks: q.marks, status: "unanswered" };
        }),
        answers: {},
        results: [],
        totals: null
    };
}

/* Answer view. Deliberately carries NO expected answer, no rubrics and no key
 * material - only what a candidate is allowed to see mid-attempt. */
function practiceQuestionView(session, questionId) {
    const bank = practiceIndexBank();
    if (!bank) return null;
    const q = bank.all.filter(function (x) { return x.id === questionId; })[0];
    if (!q) return null;
    const isOfficialMCQ = q.kind === "OFFICIAL_PAST_PAPER"
        && !!(q.mcqAnswers && Object.keys(q.mcqAnswers).length);
    return {
        id: q.id,
        kind: q.kind,
        subjectId: q.subjectId,
        type: q.type,
        difficulty: q.difficulty || null,
        text: q.text,
        marks: q.marks,
        estimatedMinutes: q.minutes || null,
        isObjective: isOfficialMCQ,
        criteriaCount: (q.criteria || []).length,
        sourceLabel: q.kind === "GENERATED_PRACTICE"
            ? "Practice question generated from the CAF study text"
            : (q.kind === "GENERATED_PAPER"
                ? "Question from a generated practice paper - not an ICAP past paper"
                : "Official ICAP past-paper question"),
        // Where the question sits in its paper. Useful on screen ("Section B,
        // question 3 of 8") and never answer material.
        paperId: q.kind === "GENERATED_PAPER" ? q.paperId : undefined,
        paperQuestionNumber: q.kind === "GENERATED_PAPER" ? q.questionNumber : undefined,
        paperSection: q.kind === "GENERATED_PAPER" ? q.section : undefined,
        // Only official Section A items carry the parsed item set - the stems and
        // option text that make the examiner's letters answerable. A generated
        // practice MCQ is a single question with A/B/C/D options; an official
        // Section A is multiple items keyed by roman numeral, each with its own
        // options. Without this the UI could only show the section banner.
        mcqItems: isOfficialMCQ ? (q.mcqItems || []) : undefined,
    };
}

/* Post-attempt view: the only place expected answers and evidence appear. */
function practiceFeedback(session, questionId) {
    const bank = practiceIndexBank();
    if (!bank) return null;
    const q = bank.all.filter(function (x) { return x.id === questionId; })[0];
    const result = (session.results || []).filter(function (r) { return r.questionId === questionId; })[0];
    if (!q || !result) return null;
    return {
        questionId: q.id,
        questionText: q.text,
        kind: q.kind,
        rubricType: q.rubricType,
        sourceLabel: q.kind === "GENERATED_PRACTICE"
            ? "Practice question generated from the CAF study text"
            : (q.kind === "GENERATED_PAPER"
                ? "Question from a generated practice paper - not an ICAP past paper"
                : "Official ICAP past-paper question with the ICAP suggested answer"),
        criteria: (q.criteria || []).map(function (c) {
            const audit = (result.criteria || []).filter(function (a) {
                return a.criterionId === c.id;
            })[0];
            return {
                criterionId: c.id,
                label: c.label || c.id,
                maxMarks: c.maxMarks,
                awarded: audit ? audit.awarded : 0,
                status: audit ? audit.status : PRACTICE_REASON.NONE,
                matchedEvidence: audit ? audit.matched : [],
                missingEvidence: audit ? audit.missing : [],
                errorType: c.errorType
            };
        }),
        awarded: result.awarded,
        marks: q.marks,
        percent: result.percent,
        unreadable: result.unreadable,
        note: result.note || null,
        expectedAnswer: practiceExpectedAnswer(q),
        // What the paper itself supplies beyond the rubric: the model workings
        // for a NUMERICAL question, and the note a SCENARIO/RECALL paper prints
        // where it has no suggested answer to give.
        workings: q.workings || "",
        markingNote: q.markingNote || "",
        grounding: q.grounding || null,
        paperId: q.paperId || null,
        studySource: q.topicId ? practiceStudyTopic(q.topicId) : null,
        examTip: (q.topicId && practiceStudyTopic(q.topicId) || {}).examTip || null,
        disclaimer: q.kind === "GENERATED_PAPER"
            ? "Practice rubric carried with the generated paper. The paper is not an ICAP past paper and this is not an official ICAP marking plan."
            : (q.rubricType === "PRACTICE_RUBRIC"
            ? "Practice rubric shaped from this subject's real papers. Not an official ICAP marking plan."
            : (q.rubricType === "OFFICIAL_MARKING_PLAN"
                ? "The option letters are the examiner's own."
                : "Practice rubric. Not an official ICAP marking plan."))
    };
}

function practiceSubmit(session, questionId, transcription) {
    const bank = practiceIndexBank();
    if (!bank || !session) return null;
    const q = bank.all.filter(function (x) { return x.id === questionId; })[0];
    if (!q) return null;
    const result = practiceMarkQuestion(q, transcription);
    session.results = (session.results || []).filter(function (r) {
        return r.questionId !== questionId;
    });
    session.results.push(result);
    session.answers[questionId] = {
        text: (transcription && transcription.text) || "",
        confidence: transcription ? transcription.confidence : null,
        provider: transcription ? transcription.provider : null,
        manual: transcription ? !!transcription.manual : null,
        submittedAt: new Date().toISOString()
    };
    const meta = (session.questions || []).filter(function (x) { return x.id === questionId; })[0];
    if (meta) meta.status = "answered";
    return result;
}

function practiceFinish(session) {
    if (!session) return null;
    const results = session.results || [];
    const marks = results.reduce(function (a, r) { return a + (r.maxMarks || 0); }, 0);
    const awarded = results.reduce(function (a, r) { return a + (r.awarded || 0); }, 0);
    const unreadable = results.filter(function (r) { return r.unreadable; }).length;
    session.finishedAt = new Date().toISOString();
    session.totals = {
        questions: results.length,
        awarded: Math.round(awarded * 100) / 100,
        marks: Math.round(marks * 100) / 100,
        percent: marks ? Math.round(awarded / marks * 1000) / 10 : 0,
        unreadable: unreadable,
        byDifficulty: {}
    };
    const bank = practiceIndexBank();
    (bank ? bank.all : []).forEach(function (q) {
        if (!q.difficulty) return;
        const r = results.filter(function (x) { return x.questionId === q.id; })[0];
        if (!r) return;
        const b = session.totals.byDifficulty[q.difficulty] ||
            (session.totals.byDifficulty[q.difficulty] = { awarded: 0, marks: 0, count: 0 });
        b.awarded += r.awarded || 0;
        b.marks += r.maxMarks || 0;
        b.count += 1;
    });
    Object.keys(session.totals.byDifficulty).forEach(function (k) {
        const b = session.totals.byDifficulty[k];
        b.percent = b.marks ? Math.round(b.awarded / b.marks * 1000) / 10 : 0;
        b.awarded = Math.round(b.awarded * 100) / 100;
    });
    return session;
}

/* =============================================================== mistake book
 * Aggregated from results, keyed by the error taxonomy so a student sees
 * "missing workings" as a pattern rather than as one bad question at a time. */

function practiceMistakeBook(sessions) {
    const tally = {};
    let items = 0;
    (sessions || []).forEach(function (s) {
        (s.results || []).forEach(function (r) {
            (r.errorsLost || []).forEach(function (e) {
                const key = e.errorType + "::" + e.criterionId;
                const t = tally[key] || (tally[key] = {
                    errorType: e.errorType,
                    criterionId: e.criterionId,
                    occurrences: 0,
                    marksLost: 0,
                    questions: {}
                });
                t.occurrences += 1;
                t.marksLost += e.marksLost || 0;
                t.questions[r.questionId] = true;
                items += 1;
            });
        });
    });
    const out = Object.keys(tally).map(function (k) {
        const t = tally[k];
        t.marksLost = Math.round(t.marksLost * 100) / 100;
        t.questionCount = Object.keys(t.questions).length;
        delete t.questions;
        return t;
    });
    out.sort(function (a, b) { return b.marksLost - a.marksLost || b.occurrences - a.occurrences; });
    return { totalErrorInstances: items, entries: out };
}

/* ==== weakness and recommendation (phase 15) ================================
 *
 * Two jobs: say what is weak, and say what to do next. Both are one pure
 * function - persisted sessions and the question index in, a report out - so
 * the screen is only a rendering of it and the same numbers can be checked
 * outside the browser.
 *
 * The rule that matters is the threshold. One badly answered question is not a
 * weakness: the candidate met the topic once, and calling it weak sends them to
 * revise material they may already hold while the real gap sits elsewhere. So
 * every row carries how many DISTINCT questions it was built from, anything
 * below PRACTICE_WEAK_MIN_ATTEMPTS is verdicted INSUFFICIENT_EVIDENCE, and the
 * only recommendation below that line is "answer more of these" - never
 * "revise this".
 *
 * Verdicts are therefore made at CHAPTER level, because this bank files one
 * generated question per topic: a topic cannot reach three attempts on its own,
 * so judging it would be judging a single answer. Chapters hold a median of
 * five questions and 111 of 127 hold three or more, which is enough to say
 * something. Topic rows are still reported - individually, with their score -
 * and read INSUFFICIENT_EVIDENCE almost every time, which is the truth.
 *
 * The recommendations are this app's own next steps rather than advice it
 * cannot keep: a study topic that exists in the mind maps, questions that have
 * NOT been attempted (counted from the bank, so the number is real), or the
 * subject's own generated paper - and never a paper to a candidate who is
 * failing that subject, which would only burn one. The hints are exam
 * technique: no tax rate, no treatment, no legal position, so none of them can
 * go stale when the law moves.
 */
const PRACTICE_WEAK_MIN_ATTEMPTS = 3;
const PRACTICE_WEAK_AT = 60;      /* below this a topic is weak */
const PRACTICE_WEAK_OK_AT = 80;   /* below this a topic is still developing */

const PRACTICE_ERROR_HINTS = {
    MISSING_POINT: "Name the requirement or rule before you apply it - a point with nothing behind it earns little.",
    CALCULATION_ERROR: "Write every arithmetic line and check the last one against the figure the question gave you.",
    WRONG_FORMULA: "Say which formula you are using and why it fits, then put the numbers into it.",
    WRONG_FINAL_ANSWER: "Carry the working through to a final figure and label it.",
    MISSING_WORKING: "Show the working. A right answer with no lines reads as luck and is marked as such.",
    MISSING_ADJUSTMENT: "You have recognised the adjustment but not quantified it - state the amount and where it lands.",
    POOR_REASONING: "Explain why: because, therefore, so that. The link is what the marks are for.",
    MISSING_CONCLUSION: "End with the answer - the figure, the recommendation, the resulting position.",
    PRESENTATION_ERROR: "One idea to a line and every figure labelled. If it cannot be read it cannot be marked.",
    APPLICATION_ERROR: "Quote the question's own facts and figures back at it instead of answering in general terms.",
    WRONG_TREATMENT: "The treatment does not fit the facts given - re-read those facts and match the rule to them.",
    WRONG_OPTION: "Objective items are marked on the examiner's own letters with no partial credit: read every option before committing.",
    NOT_ANSWERED: "Left blank. Even naming the requirement earns marks, so attempt it."
};

/* Verdict on the EVIDENCE, not on the score. `attempted` is the count of
 * distinct questions behind the percentage, so one lucky or one terrible answer
 * cannot produce a verdict at all. */
function practiceVerdictFor(attempted, percent) {
    if (!(attempted >= PRACTICE_WEAK_MIN_ATTEMPTS)) return "INSUFFICIENT_EVIDENCE";
    if (percent < PRACTICE_WEAK_AT) return "WEAK";
    if (percent < PRACTICE_WEAK_OK_AT) return "DEVELOPING";
    return "STRONG";
}

/* One pass over the study text: topic id -> the chapter it sits in. The bank
 * holds ONE generated question per topic, so a topic can never carry enough
 * attempts to be judged on its own; the chapter is the smallest unit that can.
 * Resolved once here rather than per attempt, and a topic the study text does
 * not know becomes its own chapter rather than disappearing - dropping it
 * would quietly shrink a candidate's history. */
function practiceChapterIndex() {
    const map = {};
    if (typeof mmDataStore === "undefined" || !mmDataStore) return map;
    for (const subjectId in mmDataStore) {
        if (!Object.prototype.hasOwnProperty.call(mmDataStore, subjectId)) continue;
        const chapters = mmDataStore[subjectId] || [];
        for (let i = 0; i < chapters.length; i++) {
            const ch = chapters[i];
            if (!ch) continue;
            const topics = ch.topics || [];
            for (let j = 0; j < topics.length; j++) {
                if (topics[j] && topics[j].id) {
                    map[topics[j].id] = {
                        key: subjectId + "::ch" + ch.chapterNumber,
                        title: "Ch " + ch.chapterNumber + " - " + ch.title,
                        subjectId: subjectId,
                        chapterNumber: ch.chapterNumber,
                        chapterTitle: ch.title,
                        topicTitle: topics[j].title
                    };
                }
            }
        }
    }
    return map;
}

function practiceWeaknessReport(sessions, bank, opts) {
    const o = opts || {};
    const subjectLabel = typeof o.subjectLabel === "function" ? o.subjectLabel
        : function (id) { return id; };
    const out = {
        sessions: (sessions || []).length,
        attempted: 0,
        awarded: 0,
        possible: 0,
        percent: 0,
        unreadable: 0,
        objectiveAttempts: 0,
        subjects: [],
        chapters: [],
        topics: [],
        types: [],
        errors: [],
        verdicts: { WEAK: 0, DEVELOPING: 0, STRONG: 0, INSUFFICIENT_EVIDENCE: 0 },
        insufficient: [],
        insufficientTopics: 0,
        recommendations: []
    };
    if (!bank || !(bank.all || []).length) return out;

    /* The pools are counted from the bank so a recommendation can say how many
     * questions are actually left, rather than "practise more". */
    const byId = {};
    const chapterPool = {};
    const typeTotal = {};
    const paperFor = {};
    const chapIndex = practiceChapterIndex();
    (bank.all || []).forEach(function (q) {
        byId[q.id] = q;
        const ch = q.topicId ? chapIndex[q.topicId] : null;
        /* Counted for GENERATED PRACTICE only, because that is what the "answer
         * what is left" action can actually serve. Promising a paper question
         * here and then not having it would be a recommendation that lies. */
        if (ch && q.kind === "GENERATED_PRACTICE") {
            chapterPool[ch.key] = (chapterPool[ch.key] || 0) + 1;
        }
        const t = q.type || "UNSPECIFIED";
        if (q.kind === "GENERATED_PRACTICE") {
            typeTotal[t] = (typeTotal[t] || 0) + 1;
        }
    });
    function chapterFor(topicId, subjectId) {
        if (!topicId) return null;
        if (chapIndex[topicId]) return chapIndex[topicId];
        return {
            key: subjectId + "::topic::" + topicId,
            title: topicId, subjectId: subjectId,
            chapterNumber: null, chapterTitle: "", topicTitle: topicId
        };
    }
    (bank.paperList || []).forEach(function (p) {
        if (p.subject && p.paperId && !paperFor[p.subject]) paperFor[p.subject] = p.paperId;
    });

    const subjMap = {};
    const chapterMap = {};
    const topicMap = {};
    const typeMap = {};
    const errMap = {};

    function bucket(map, key, seed) {
        let b = map[key];
        if (!b) {
            b = map[key] = seed;
            b.attempted = 0;
            b.awarded = 0;
            b.possible = 0;
            b.unique = 0;
            b.seen = {};
        }
        b.attempted += 1;
        return b;
    }

    function note(map, key, seed, questionId, awarded, possible) {
        const b = bucket(map, key, seed);
        b.awarded += awarded;
        b.possible += possible;
        if (!b.seen[questionId]) {
            b.seen[questionId] = 1;
            b.unique += 1;
        }
        return b;
    }

    (sessions || []).forEach(function (s) {
        if (!s || !(s.results || []).length) return;
        (s.results || []).forEach(function (r) {
            if (!r || !r.questionId) return;
            const q = byId[r.questionId];
            const possible = r.maxMarks || 0;
            const awarded = r.awarded || 0;
            if (!possible) return;   /* nothing to judge it against */
            const lost = Math.round((possible - awarded) * 100) / 100;
            const subjectId = (q && q.subjectId) || s.subjectId || "unknown";
            const type = (q && q.type) || "UNSPECIFIED";
            const topicId = (q && q.topicId) || null;

            out.attempted += 1;
            out.awarded += awarded;
            out.possible += possible;
            if (r.unreadable) out.unreadable += 1;
            if (r.mcq) out.objectiveAttempts += 1;

            note(subjMap, subjectId, { id: subjectId }, r.questionId, awarded, possible);
            note(typeMap, type, { id: type }, r.questionId, awarded, possible);
            if (topicId) {
                const ch = chapterFor(topicId, subjectId);
                note(topicMap, topicId, {
                    id: topicId, subjectId: subjectId,
                    chapter: ch ? ch.key : null,
                    chapterTitle: ch ? ch.title : ""
                }, r.questionId, awarded, possible);
                if (ch) {
                    note(chapterMap, ch.key,
                        { id: ch.key, title: ch.title, subjectId: subjectId },
                        r.questionId, awarded, possible);
                }
            }

            (r.errorsLost || []).forEach(function (e) {
                const key = e.errorType || "UNSPECIFIED";
                let b = errMap[key];
                if (!b) {
                    b = errMap[key] = {
                        errorType: key, occurrences: 0, marksLost: 0, questions: {}
                    };
                }
                b.occurrences += 1;
                b.marksLost += e.marksLost || 0;
                b.questions[r.questionId] = 1;
            });

            /* An objective result returns before the criteria are scored, so it
             * carries no errorsLost at all. Without this branch every mark an
             * MCQ set lost would be missing from the tally, and the report
             * would tell a candidate dropping objective marks that they never
             * lose any. */
            if (r.mcq && lost > 0) {
                let b = errMap.WRONG_OPTION;
                if (!b) {
                    b = errMap.WRONG_OPTION = {
                        errorType: "WRONG_OPTION", occurrences: 0, marksLost: 0, questions: {}
                    };
                }
                b.occurrences += Math.max(1, (r.mcq.itemCount || 0) - (r.mcq.right || 0));
                b.marksLost += lost;
                b.questions[r.questionId] = 1;
            }
        });
    });

    out.awarded = Math.round(out.awarded * 100) / 100;
    out.percent = out.possible ? Math.round(out.awarded / out.possible * 1000) / 10 : 0;

    function finish(map) {
        return Object.keys(map).map(function (key) {
            const b = map[key];
            b.percent = b.possible ? Math.round(b.awarded / b.possible * 1000) / 10 : 0;
            b.marksLost = Math.round((b.possible - b.awarded) * 100) / 100;
            /* Evidence first: unique questions, never raw attempt count. */
            b.verdict = practiceVerdictFor(b.unique, b.percent);
            delete b.seen;
            return b;
        });
    }
    function worstFirst(a, b) {
        return (b.marksLost - a.marksLost) || (a.percent - b.percent)
            || String(a.id).localeCompare(String(b.id));
    }
    out.subjects = finish(subjMap).sort(worstFirst);
    out.chapters = finish(chapterMap).sort(worstFirst);
    out.types = finish(typeMap).sort(worstFirst);
    out.topics = finish(topicMap).sort(worstFirst);

    out.errors = Object.keys(errMap).map(function (key) {
        const b = errMap[key];
        b.marksLost = Math.round(b.marksLost * 100) / 100;
        b.questionCount = Object.keys(b.questions).length;
        b.hint = PRACTICE_ERROR_HINTS[b.errorType]
            || "Open the feedback on one of these and match your answer against the criterion it lost marks on.";
        delete b.questions;
        return b;
    }).sort(function (a, b) {
        return (b.marksLost - a.marksLost) || (b.occurrences - a.occurrences)
            || String(a.errorType).localeCompare(String(b.errorType));
    });

    out.insufficient = out.chapters.filter(function (c) {
        return c.verdict === "INSUFFICIENT_EVIDENCE" && c.attempted;
    }).map(function (c) {
        return {
            chapterId: c.id, subjectId: c.subjectId, title: c.title,
            attempted: c.unique, percent: c.percent
        };
    });
    out.chapters.forEach(function (c) {
        if (out.verdicts[c.verdict] !== undefined) out.verdicts[c.verdict] += 1;
    });
    out.insufficientTopics = out.topics.filter(function (t) {
        return t.verdict === "INSUFFICIENT_EVIDENCE" && t.attempted;
    }).length;

    /* ---- recommendations -------------------------------------------------
     * Ordered by how directly they can be acted on: the topic to revise, the
     * question type to drill, the paper to sit, the evidence still missing,
     * and the technique that is costing the most marks. */
    const recs = [];
    function count(kind) {
        return recs.filter(function (r) { return r.kind === kind; }).length;
    }
    function topicTitleOf(topicId) {
        return (chapIndex[topicId] && chapIndex[topicId].topicTitle) || topicId;
    }

    /* STUDY: a chapter that is weak on enough evidence. The open target is the
     * topic inside it that lost the most, because someone who has just scored
     * 25% does not need the chapter's front page - they need the part that
     * hurt. */
    out.chapters.forEach(function (c) {
        if (c.verdict !== "WEAK" || count("STUDY") >= 4) return;
        const left = Math.max(0, (chapterPool[c.id] || 0) - c.unique);
        const inside = out.topics.filter(function (t) { return t.chapter === c.id; })
            .sort(function (a, b) {
                return (a.percent - b.percent) || (b.marksLost - a.marksLost);
            });
        const target = inside[0];
        if (!target) return;
        recs.push({
            kind: "STUDY",
            topicId: target.id,
            chapterId: c.id,
            subjectId: c.subjectId,
            attempts: c.unique,
            percent: c.percent,
            marksLost: c.marksLost,
            available: left,
            text: "Revise " + c.title + ": " + c.percent + "% across "
                + c.unique + " question(s) and " + c.marksLost
                + " mark(s) lost."
                + (left ? " Then answer the " + left + " question(s) in it you have not tried."
                        : " You have sat every question in it, so revise and then retake it.")
                + (target.percent < 50
                    ? " Start with \"" + topicTitleOf(target.id) + "\", which is "
                      + target.percent + "%."
                    : "")
        });
    });

    out.types.forEach(function (t) {
        if (t.verdict !== "WEAK" || count("PRACTICE") >= 2) return;
        const left = typeTotal[t.id] || 0;
        if (!left) return;
        recs.push({
            kind: "PRACTICE",
            type: t.id,
            attempts: t.unique,
            percent: t.percent,
            available: left,
            text: "Answer more " + String(t.id).toLowerCase() + " questions: "
                + t.percent + "% across " + t.unique + " so far, and " + left
                + " of them are available."
        });
    });

    out.subjects.filter(function (s) {
        return paperFor[s.id]
            && (s.verdict === "STRONG" || s.verdict === "DEVELOPING");
    }).sort(function (a, b) {
        return b.percent - a.percent || String(a.id).localeCompare(String(b.id));
    }).slice(0, 2).forEach(function (s) {
        recs.push({
            kind: "PAPER",
            subjectId: s.id,
            paperId: paperFor[s.id],
            attempts: s.unique,
            percent: s.percent,
            available: 1,
            text: "Sit " + paperFor[s.id] + " under paper conditions - "
                + subjectLabel(s.id) + " is at " + s.percent + "% across "
                + s.unique + " question(s)."
        });
    });

    /* MORE_ATTEMPTS: looks weak, not yet proven. The honest answer is more
     * evidence, so the action is a session of the chapter's own unattempted
     * questions rather than a verdict. */
    out.insufficient.filter(function (c) {
        return c.percent < PRACTICE_WEAK_OK_AT;
    }).sort(function (a, b) {
        return a.percent - b.percent || String(a.chapterId).localeCompare(String(b.chapterId));
    }).slice(0, 3).forEach(function (c) {
        const left = Math.max(0, (chapterPool[c.chapterId] || 0) - c.attempted);
        const need = Math.max(1, PRACTICE_WEAK_MIN_ATTEMPTS - c.attempted);
        recs.push({
            kind: "MORE_ATTEMPTS",
            chapterId: c.chapterId,
            subjectId: c.subjectId,
            attempts: c.attempted,
            percent: c.percent,
            available: left,
            text: c.title + " is " + c.percent + "% after " + c.attempted
                + " question(s), which is not enough evidence for a verdict yet."
                + (left ? " Answer " + Math.min(left, need) + " of the " + left
                        + " you have not tried."
                        : " You have sat every question in it; retake it after revising.")
        });
    });

    out.errors.filter(function (e) {
        return e.marksLost > 0;
    }).slice(0, 3).forEach(function (e) {
        recs.push({
            kind: "TECHNIQUE",
            errorType: e.errorType,
            attempts: e.questionCount,
            marksLost: e.marksLost,
            percent: null,
            available: 0,
            text: String(e.errorType).replace(/_/g, " ").toLowerCase() + ": " + e.hint
                + " (" + e.marksLost + " mark(s) lost across " + e.questionCount
                + " question(s).)"
        });
    });

    out.recommendations = recs.slice(0, 12).map(function (r, i) {
        r.rank = i + 1;
        return r;
    });
    return out;
}

/* ==== analytics (phase 16) ==================================================
 *
 * The weakness report answers "what should I fix"; analytics answers "what has
 * actually been done" - volume, reach, mix and direction. Same inputs,
 * deliberately different questions, so the two screens can never contradict
 * each other, and neither grades a topic or names an action.
 *
 * Three honesty rules are built in rather than added afterwards:
 *
 *   - DIRECTION: reported only between two halves of the history that both
 *     contain marks, and movement under PRACTICE_ANALYTICS_FLAT_POINTS points
 *     is reported as "no clear change". Two flat scores are not progress and
 *     two bad scores are not a collapse; saying otherwise would be reading a
 *     story into noise, and the number is small enough that a candidate would
 *     believe it.
 *
 *   - DURATION: a sitting that is negative or longer than
 *     PRACTICE_ANALYTICS_MAX_MINUTES is discarded and COUNTED as discarded.
 *     Averaging a bad clock into a headline time produces a figure nobody can
 *     question and everybody should.
 *
 *   - MIX: objective and written rates are shown side by side and never summed
 *     or ranked against each other, because objective items carry no partial
 *     credit. A lower objective rate is a different measurement, not a worse
 *     candidate.
 *
 * Nothing here forecasts a grade or an outcome. History is descriptive.
 */
const PRACTICE_ANALYTICS_FLAT_POINTS = 5;
const PRACTICE_ANALYTICS_MAX_MINUTES = 480;   /* one sitting, generously */

function practiceAnalyticsReport(sessions, bank) {
    const out = {
        sessions: 0,
        attempted: 0, awarded: 0, possible: 0, percent: 0,
        daysActive: 0, lastActivity: null, historyLimit: 50,
        unreadable: 0, unreadableRate: 0,
        typed: 0, transcribed: 0, lowConfidence: 0,
        objective: { count: 0, awarded: 0, possible: 0, percent: 0 },
        written: { count: 0, awarded: 0, possible: 0, percent: 0 },
        coverage: {
            total: 0, reached: 0, percent: 0,
            subjects: [], untouchedSubjects: [],
            chaptersTotal: 0, chaptersReached: 0
        },
        bySource: [],
        byDifficulty: [],
        trend: {
            points: [], enough: false,
            firstHalf: null, secondHalf: null, delta: 0,
            direction: "UNKNOWN", best: null, worst: null
        },
        time: {
            measured: 0, ignored: 0, unmeasured: 0, minutes: 0, questions: 0,
            avgPerSession: 0, avgPerQuestion: 0
        }
    };
    if (!bank || !(bank.all || []).length) return out;

    const byId = {};
    const subjAvailable = {};
    const chapIndex = practiceChapterIndex();
    const bankChapters = {};
    (bank.all || []).forEach(function (q) {
        byId[q.id] = q;
        subjAvailable[q.subjectId] = (subjAvailable[q.subjectId] || 0) + 1;
        const ch = q.topicId ? chapIndex[q.topicId] : null;
        if (ch) bankChapters[ch.key] = 1;
    });

    const reachedQ = {};
    const reachedChapter = {};
    const reachedBySubject = {};
    const days = {};
    const srcMap = {};
    const diffMap = {};
    const points = [];
    let typed = 0;
    let transcribed = 0;
    let lowConf = 0;
    let objCount = 0;
    let objAwarded = 0;
    let objPossible = 0;
    let wrCount = 0;
    let wrAwarded = 0;
    let wrPossible = 0;
    let tMeasured = 0;
    let tIgnored = 0;
    let tUnmeasured = 0;
    let tMinutes = 0;
    let tQuestions = 0;

    function round2(n) { return Math.round(n * 100) / 100; }
    function round1(n) { return Math.round(n * 10) / 10; }
    /* A duration is only evidence when the clock could have been running. */
    function durationOf(s) {
        if (!s.startedAt || !s.finishedAt) return null;
        const ms = Date.parse(s.finishedAt) - Date.parse(s.startedAt);
        if (isNaN(ms) || ms < 0 || ms > PRACTICE_ANALYTICS_MAX_MINUTES * 60000) {
            return null;
        }
        return round1(ms / 60000);
    }

    (sessions || []).forEach(function (s) {
        if (!s || !(s.results || []).length) return;
        out.sessions += 1;

        const when = s.finishedAt || s.startedAt || null;
        if (when) days[String(when).slice(0, 10)] = 1;
        if (when && (!out.lastActivity || String(when) > String(out.lastActivity))) {
            out.lastActivity = when;
        }

        let sAwarded = 0;
        let sPossible = 0;
        let sQuestions = 0;
        (s.results || []).forEach(function (r) {
            if (!r || !r.questionId) return;
            const q = byId[r.questionId];
            const possible = r.maxMarks || 0;
            const awarded = r.awarded || 0;
            if (!possible) return;

            out.attempted += 1;
            out.awarded += awarded;
            out.possible += possible;
            if (r.unreadable) out.unreadable += 1;
            sAwarded += awarded;
            sPossible += possible;
            sQuestions += 1;

            if (!reachedQ[r.questionId]) {
                reachedQ[r.questionId] = 1;
                if (q) {
                    reachedBySubject[q.subjectId] =
                        (reachedBySubject[q.subjectId] || 0) + 1;
                }
            }
            if (q) {
                const ch = q.topicId ? chapIndex[q.topicId] : null;
                if (ch) reachedChapter[ch.key] = 1;

                const src = q.kind || "UNKNOWN";
                const sb = srcMap[src] || (srcMap[src] = { id: src, count: 0, awarded: 0, possible: 0 });
                sb.count += 1;
                sb.awarded += awarded;
                sb.possible += possible;

                const df = q.difficulty || "UNSET";
                const db = diffMap[df] || (diffMap[df] = { id: df, count: 0, awarded: 0, possible: 0 });
                db.count += 1;
                db.awarded += awarded;
                db.possible += possible;
            }

            if (q && q.type === "OBJECTIVE_MCQ") {
                objCount += 1;
                objAwarded += awarded;
                objPossible += possible;
            } else {
                wrCount += 1;
                wrAwarded += awarded;
                wrPossible += possible;
            }
        });

        /* Provenance of what was submitted: read out of the answer record,
         * because the mark itself never carries the transcription's
         * confidence or whether a human typed it. */
        const answers = s.answers || {};
        Object.keys(answers).forEach(function (qid) {
            const a = answers[qid];
            if (!a) return;
            if (a.manual) typed += 1;
            else transcribed += 1;
            if (typeof a.confidence === "number" && a.confidence < OCR_MIN_CONFIDENCE) {
                lowConf += 1;
            }
        });

        const mins = durationOf(s);
        if (mins === null) {
            if (s.startedAt && s.finishedAt) tIgnored += 1;
            else tUnmeasured += 1;
        } else {
            tMeasured += 1;
            tMinutes += mins;
            tQuestions += sQuestions;
        }

        points.push({
            sessionId: s.sessionId || ("session-" + out.sessions),
            date: when,
            label: s.label || s.mode || "",
            questions: sQuestions,
            awarded: round2(sAwarded),
            marks: round2(sPossible),
            percent: sPossible ? round1(sAwarded / sPossible * 100) : 0,
            minutes: mins
        });
    });

    out.awarded = round2(out.awarded);
    out.percent = out.possible ? round1(out.awarded / out.possible * 100) : 0;
    out.daysActive = Object.keys(days).length;
    out.unreadableRate = out.attempted
        ? round1(out.unreadable / out.attempted * 100) : 0;
    out.typed = typed;
    out.transcribed = transcribed;
    out.lowConfidence = lowConf;

    out.objective.count = objCount;
    out.objective.awarded = round2(objAwarded);
    out.objective.possible = round2(objPossible);
    out.objective.percent = objPossible ? round1(objAwarded / objPossible * 100) : 0;
    out.written.count = wrCount;
    out.written.awarded = round2(wrAwarded);
    out.written.possible = round2(wrPossible);
    out.written.percent = wrPossible ? round1(wrAwarded / wrPossible * 100) : 0;

    /* ---- coverage: how much of the bank has been touched ------------------ */
    out.coverage.total = (bank.all || []).length;
    out.coverage.reached = Object.keys(reachedQ).length;
    out.coverage.percent = out.coverage.total
        ? round1(out.coverage.reached / out.coverage.total * 100) : 0;
    out.coverage.chaptersTotal = Object.keys(bankChapters).length;
    out.coverage.chaptersReached = Object.keys(reachedChapter).length;
    out.coverage.subjects = Object.keys(subjAvailable).map(function (id) {
        const available = subjAvailable[id];
        const reached = reachedBySubject[id] || 0;
        return {
            subjectId: id,
            available: available,
            reached: reached,
            percent: available ? round1(reached / available * 100) : 0
        };
    }).sort(function (a, b) {
        return (a.percent - b.percent) || (b.available - a.available)
            || String(a.subjectId).localeCompare(String(b.subjectId));
    });
    out.coverage.untouchedSubjects = out.coverage.subjects
        .filter(function (s) { return !s.reached; })
        .map(function (s) { return s.subjectId; });

    function finishMix(map) {
        return Object.keys(map).map(function (k) {
            const b = map[k];
            b.percent = b.possible ? round1(b.awarded / b.possible * 100) : 0;
            b.awarded = round2(b.awarded);
            b.possible = round2(b.possible);
            return b;
        }).sort(function (a, b) {
            return (b.count - a.count) || String(a.id).localeCompare(String(b.id));
        });
    }
    out.bySource = finishMix(srcMap);
    out.byDifficulty = finishMix(diffMap);

    /* ---- direction: two halves, both with marks --------------------------- */
    points.sort(function (a, b) {
        const ad = a.date ? Date.parse(a.date) : NaN;
        const bd = b.date ? Date.parse(b.date) : NaN;
        if (isNaN(ad) && isNaN(bd)) return 0;
        if (isNaN(ad)) return -1;
        if (isNaN(bd)) return 1;
        return ad - bd;
    });
    out.trend.points = points;
    const scored = points.filter(function (p) { return p.marks > 0; });
    if (scored.length >= 2) {
        const half = Math.floor(scored.length / 2);
        const first = scored.slice(0, half);
        const second = scored.slice(half);
        const sum = function (rows, key) {
            return rows.reduce(function (a, p) { return a + p[key]; }, 0);
        };
        const fa = sum(first, "awarded");
        const fm = sum(first, "marks");
        const sa = sum(second, "awarded");
        const sm = sum(second, "marks");
        out.trend.enough = fm > 0 && sm > 0;
        if (out.trend.enough) {
            out.trend.firstHalf = round1(fa / fm * 100);
            out.trend.secondHalf = round1(sa / sm * 100);
            out.trend.delta = round1(out.trend.secondHalf - out.trend.firstHalf);
            out.trend.direction = out.trend.delta >= PRACTICE_ANALYTICS_FLAT_POINTS ? "UP"
                : (out.trend.delta <= -PRACTICE_ANALYTICS_FLAT_POINTS ? "DOWN" : "FLAT");
        }
        const ranked = scored.slice().sort(function (a, b) { return b.percent - a.percent; });
        out.trend.best = { date: ranked[0].date, percent: ranked[0].percent, sessionId: ranked[0].sessionId };
        out.trend.worst = { date: ranked[ranked.length - 1].date,
            percent: ranked[ranked.length - 1].percent,
            sessionId: ranked[ranked.length - 1].sessionId };
    }

    out.time.measured = tMeasured;
    out.time.ignored = tIgnored;
    out.time.unmeasured = tUnmeasured;
    out.time.minutes = round1(tMinutes);
    out.time.questions = tQuestions;
    out.time.avgPerSession = tMeasured ? round1(tMinutes / tMeasured) : 0;
    out.time.avgPerQuestion = tQuestions ? round1(tMinutes / tQuestions) : 0;
    return out;
}

/* ============================================================================
   CONTENT REVIEW REPORT (phase 17, admin review/approval - the browser half)

   The build-time register (var REVIEW_REGISTER, emitted by
   build_review_register.py) records what the pipeline verified against the
   supplied papers, which the app cannot re-check because those papers do not
   ship here. This function re-runs everything the app CAN re-check over the
   bank that is actually loaded, and the review screen shows both halves side
   by side.

   The checks are failures of content, not of style: each one measures a
   question, paper or criterion nobody should be marked against. An empty list
   means no failure; a non-empty one is listed by id so a reviewer can find it.
   ============================================================================ */
function practiceReviewReport(bank, register) {
    if (!bank) return null;
    const reg = register || (typeof REVIEW_REGISTER !== "undefined" && REVIEW_REGISTER
        ? REVIEW_REGISTER : null);
    const verbs = {};
    const channels = {};
    const objectiveChannels = {};
    (reg && reg.rubricVerbs || []).forEach(function (v) {
        verbs[String(v).toLowerCase()] = true;
    });
    (reg && reg.channels || []).forEach(function (c) {
        channels[c] = true;
    });
    (reg && reg.objectiveChannels || []).forEach(function (c) {
        objectiveChannels[c] = true;
    });
    const LIST = { keyPointTerms: true, formulaTerms: true };
    const CAP = 24;
    const round2 = function (n) { return Math.round(n * 100) / 100; };
    const chapterIndex = practiceChapterIndex();
    const checks = [];
    let failures = 0;
    let criteriaCount = 0;
    let termCount = 0;
    let listCriteria = 0;

    function add(id, name, purpose, checked, failed, rows) {
        failures += failed ? 1 : 0;
        checks.push({
            id: id, name: name, purpose: purpose, checked: checked, failed: failed,
            status: failed ? "FAIL" : "PASS", failures: rows.slice(0, CAP)
        });
    }

    /* ---- source traceability ------------------------------------------- */
    const untraceable = [];
    const marksBad = [];
    const vocabBad = [];
    const dead = [];
    const verbBad = [];
    const placeBad = [];
    const thin = [];
    bank.all.forEach(function (q) {
        if (q.kind === "GENERATED_PRACTICE"
            && (!q.topicId || !chapterIndex[q.topicId])) {
            untraceable.push({ id: q.id, subjectId: q.subjectId,
                why: "topicId " + q.topicId + " resolves to no study-text chapter" });
        }
        if ((q.criteria || []).length) {
            const paid = round2((q.criteria || []).reduce(function (a, c) {
                return a + (c.maxMarks || 0);
            }, 0));
            if (Math.abs(paid - round2(q.marks || 0)) > 0.01) {
                marksBad.push({ id: q.id, subjectId: q.subjectId,
                    why: "criteria pay " + paid + " of " + q.marks });
            }
        }
        const objective = q.type === "OBJECTIVE_MCQ";
        (q.criteria || []).forEach(function (c) {
            criteriaCount++;
            const known = channels[c.evidence] || objectiveChannels[c.evidence];
            if (!known) {
                vocabBad.push({ id: q.id, subjectId: q.subjectId,
                    why: "channel '" + c.evidence + "' is not scored by name" });
            }
            if (objectiveChannels[c.evidence] && !objective) {
                placeBad.push({ id: q.id, subjectId: q.subjectId,
                    why: "objective channel on a " + q.type + " question" });
            }
            if (LIST[c.evidence]) {
                listCriteria++;
                const terms = (q.evidenceTerms && q.evidenceTerms[c.id]) || c.terms || [];
                termCount += terms.length;
                if (!terms.length) {
                    dead.push({ id: q.id, subjectId: q.subjectId,
                        why: "no evidence list for " + c.id });
                } else {
                    if (terms.length < 3) {
                        thin.push({ id: q.id, subjectId: q.subjectId,
                            why: c.id + " has " + terms.length + " terms" });
                    }
                    terms.forEach(function (w) {
                        if (verbs[String(w).toLowerCase()]) {
                            verbBad.push({ id: q.id, subjectId: q.subjectId,
                                why: "term '" + w + "' is a marker verb" });
                        }
                    });
                }
            }
        });
    });
    add("SOURCE_TRACE", "Questions resolve to the study text",
        "A generated question whose topicId has no chapter in the study text has "
        + "no academic source: it cannot be traced, revised from, or defended.",
        bank.generated.length, untraceable.length, untraceable);
    add("RUBRIC_SUMS", "Criteria pay the marks printed on the question",
        "If a rubric's criteria do not add up to the marks on the question, the "
        + "question's own ceiling is a number the rubric cannot pay.",
        bank.all.length, marksBad.length, marksBad);
    add("CHANNEL_VOCAB", "Every evidence channel is scored by name",
        "A criterion on a channel the marker does not switch on falls through to "
        + "the default scoring path, which is not what the rubric designed it as.",
        criteriaCount, vocabBad.length, vocabBad);
    add("EVIDENCE_LIST", "Word-scored criteria carry the words to score",
        "The marker reads an empty list as no evidence recorded and returns "
        + "zero for that criterion in every answer, while the question keeps "
        + "showing its full marks.",
        termCount ? listCriteria : criteriaCount, dead.length, dead);
    add("MARKER_VERBS", "No marker verb inside a term list",
        "A study text reading 'the standard states ...' would otherwise make "
        + "'states' worth a mark, collectible by quoting the question back.",
        termCount, verbBad.length, verbBad);
    add("MCQ_PLACEMENT", "Objective keying used only on objective questions",
        "The objective answer-key channel belongs to nothing else; a written "
        + "question carrying it would be scored by the wrong path.",
        criteriaCount, placeBad.length, placeBad);

    /* ---- provenance and marking sources --------------------------------- */
    const provBad = [];
    (bank.paperList || []).forEach(function (p) {
        const pr = p.provenance || {};
        if (!(pr.generated === true && pr.officialICAP === false
            && pr.copiedFromPastPapers === false)) {
            provBad.push({ id: p.paperId, subjectId: p.subjectId || "",
                why: "provenance must declare generated, not-ICAP, not-copied" });
        }
    });
    add("PROVENANCE", "Every generated paper declares what it is",
        "A paper that does not assert generated/not-official-ICAP/not-copied "
        + "could be mistaken for an ICAP past paper, and the app refuses it.",
        (bank.paperList || []).length, provBad.length, provBad);

    const noKey = [];
    const keyBad = [];
    let objectiveCount = 0;
    bank.official.forEach(function (q) {
        if (!q.answerDocId) {
            noKey.push({ id: q.id, subjectId: q.subjectId,
                why: "no suggested-answer document id recorded" });
        }
        if (q.type === "OBJECTIVE_MCQ") {
            objectiveCount++;
            const keys = Object.keys(q.mcqAnswers || {}).length;
            const items = (q.mcqItems || []).length;
            if (keys !== items) {
                keyBad.push({ id: q.id, subjectId: q.subjectId,
                    why: keys + " keys for " + items + " items" });
            }
        }
    });
    add("MARKING_SOURCE", "Official questions name their marking source",
        "An official question without its suggested-answer document id claims a "
        + "marking source it cannot show.",
        bank.official.length, noKey.length, noKey);
    add("MCQ_KEYING", "One key per item shown",
        "The marker awards an objective section pro rata over its keys; a key "
        + "the candidate was never shown is a mark nobody can win.",
        objectiveCount, keyBad.length, keyBad);

    /* ---- watch items (reported, not gating) ------------------------------ */
    const watch = [];
    watch.push({
        id: "THIN_EVIDENCE", count: thin.length,
        why: "Evidence lists under three terms are narrow: the marker can only "
            + "match what is listed, so an answer in different words scores "
            + "nothing for that criterion. Formula criteria are built from short "
            + "source sentences, so this is reported for a human rather than "
            + "failed as a defect.",
        sample: thin.slice(0, 6)
    });

    /* ---- register vs loaded bank: drift ---------------------------------- */
    /* `chapterIndex` maps study topics to their chapter, so its size is the
     * topic count. The register counts chapters the way the bank builder does
     * - the distinct chapters that carry a generated question - so the live
     * side reproduces that same definition through the index, and the topic
     * count is compared against the register's own studyTopics. Every drift
     * row then compares like with like. */
    const drift = [];
    function driftRow(label, registered, live) {
        if (registered === null || registered === undefined) return;
        drift.push({ label: label, registered: registered, live: live,
            matches: registered === live });
    }
    const usedChapters = {};
    (bank.generated || []).forEach(function (q) {
        const info = chapterIndex[q.topicId];
        if (info && info.key) usedChapters[info.key] = true;
    });
    const liveChapters = Object.keys(usedChapters).length;
    driftRow("generated", reg && reg.counts && reg.counts.generated,
        bank.generated.length);
    driftRow("official", reg && reg.counts && reg.counts.official, bank.official.length);
    driftRow("paper questions", reg && reg.counts && reg.counts.paperQuestions,
        bank.paperQuestions.length);
    driftRow("papers", reg && reg.counts && reg.counts.papers, bank.paperList.length);
    driftRow("subjects", reg && reg.counts && reg.counts.subjects,
        Object.keys(bank.bySubject || {}).length);
    driftRow("chapters", reg && reg.counts && reg.counts.chapters, liveChapters);
    driftRow("study topics", reg && reg.counts && reg.counts.studyTopics,
        Object.keys(chapterIndex).length);

    const out = {
        ok: failures === 0,
        digest: bank.all.length + "/" + bank.generated.length
            + "/" + bank.official.length + "/" + bank.paperQuestions.length
            + "/" + bank.paperList.length + "@" + (reg && reg.builtAt || "unregistered"),
        builtAt: (reg && reg.builtAt) || null,
        checks: checks,
        watch: watch,
        drift: drift,
        register: reg,
        counts: {
            questions: bank.all.length, generated: bank.generated.length,
            official: bank.official.length, paperQuestions: bank.paperQuestions.length,
            papers: bank.paperList.length,
            subjects: Object.keys(bank.bySubject || {}).length,
            chapters: liveChapters,
            studyTopics: Object.keys(chapterIndex).length
        }
    };
    return out;
}

/* ==== end of CAF Practice Centre engine fragment ==== */
/* ============================ CAF Practice Centre UI ============================
 * The face of the practice engine (see _frag_practice_engine.js).
 *
 * Scope decision: this does NOT replace the existing chapter-wise MCQ practice
 * centre. It ships as a self-contained overlay with its own launcher, because
 * the MCQ quiz re-renders `#practice-main-container` wholesale and anything
 * injected in there would be destroyed on the next subject switch. The launcher
 * lives in its own container inside #view-practice and the session itself lives
 * in an overlay on <body>, so neither can be clobbered.
 *
 * The one thing that matters most here is that an expected answer never reaches
 * the DOM during an attempt. `practiceQuestionView` is the only question source
 * used while a session is live, and it carries no answer material at all.
 * ============================================================================= */

const PRACTICE_CENTRE_LAUNCHER_ID = 'practice-centre-launcher';
const PRACTICE_CENTRE_OVERLAY_ID = 'practice-centre-overlay';

/* Subject labels are DERIVED from `mmSubjectsList`, the app's own subject table.
 *
 * This used to be a second hand-written list of the same eight subjects, and there
 * were three names in play rather than one: the app's table, this list, and whatever
 * name each supplied past paper prints on its own cover. Three lists is two more
 * than there should be, and they had already drifted - this one said "Taxation"
 * where both the app's table and the papers say "Taxation Principles & Compliance",
 * and "Business & Company Law" where the app's table says "Business Law Dynamics".
 * Any future correction to a subject name would have had to be made in the right one
 * of three places, and there was nothing that could tell you which.
 *
 * Deriving the label from mmSubjectsList removes the duplicate: the Practice Centre
 * can only display the name the rest of the app displays.
 *
 * `corpusName` is what the supplied PAST PAPERS call the same subject, read off their
 * covers and carried in PRACTICE_BANK.subjectNames. Where it differs from the app's
 * name the difference is kept, not resolved here. CAF-6 is the live case: both
 * supplied CAF-6 papers print "Corporate Reporting" on their cover, while the app's
 * subject table - built from the study text CAF-6-ST.pdf - says "Managerial &
 * Financial Analysis". Those are different subjects, not two spellings of one, so
 * `practiceCentreNameConflicts` records the pair and the app decides what to show.
 */
/* Return the CAF subjects, in the app's own order, from `mmSubjectsList`.
 *
 * The list of ids is derived too, and it has to be. This used to enumerate
 * 'caf1' ... 'caf8' literally, which looks correct and is not: the app carries a
 * NINTH CAF row, `caf4v2` - "CAF 4 - VOL 2, Business Law Dynamics - Vol II" - and
 * the generated bank holds 46 Vol II questions under that id. Selecting by the
 * literal list left all 46 unreachable, while the screen cheerfully counted 56
 * questions for CAF-4 (46 Vol I plus 10 official) as though nothing were missing.
 * A count that silently omits a fifth of the bank is worse than no count.
 *
 * The volume is not repeated in the label. `mmSubjectsList` already says "Vol I" or
 * "Vol II" in the name and "VOL 1"/"VOL 2" in the code; printing "CAF-4v2" as well
 * would say the same thing a third way. Only the subject number is added, taken from
 * the digits of the id, so both volumes read CAF-4 and are told apart by their names.
 */
function practiceCentreCafSubjects() {
    const rows = (typeof mmSubjectsList !== 'undefined' && mmSubjectsList
        && mmSubjectsList) ? mmSubjectsList : [];
    return rows.filter(function (s) {
        return s && typeof s.id === 'string' && /^caf\d/i.test(s.id);
    });
}

/* Every subject id here is also the id the question bank uses, so nothing needs
 * translating today. `bankIds` exists so that IF the study texts and the bank
 * ever disagree about a subject again, one row can carry both spellings and
 * every lookup resolves either - rather than the row quietly matching nothing.
 *
 * That was checked rather than assumed: an earlier reading of the subject list
 * suggested the dropdown called Business Law Vol 1 `caf4v1` while the bank
 * called it `caf4`, which would have made all 46 of its questions unreachable.
 * The page uses `caf4` for both, so the alias table was removed rather than left
 * in place covering an id that does not exist. */
const PRACTICE_CENTRE_SUBJECT_ALIASES = {};

const PRACTICE_CENTRE_SUBJECTS = (function () {
    const byId = {};
    (typeof mmSubjectsList !== 'undefined' && mmSubjectsList ? mmSubjectsList : [])
        .forEach(function (s) { if (s && s.id) byId[s.id] = s; });
    const corpusNames = (typeof PRACTICE_BANK !== 'undefined' && PRACTICE_BANK
        && PRACTICE_BANK.subjectNames) ? PRACTICE_BANK.subjectNames : {};
    return practiceCentreCafSubjects().map(function (s) {
        const id = s.id;
        const num = (id.match(/^caf(\d+)/i) || ['', ''])[1];
        const name = s.name || id;
        const bankIds = [id];
        const alias = PRACTICE_CENTRE_SUBJECT_ALIASES[id];
        if (alias) bankIds.push(alias);
        return {
            id: id,
            bankIds: bankIds,
            label: (num ? 'CAF-' + num + ' ' : '') + name,
            shortName: s.shortName || '',
            appName: name,
            color: s.color || '',
            corpusName: (corpusNames[id] && corpusNames[id].name) || null
        };
    });
})();

/* Resolve a subject row from EITHER the app's id or the bank's. Business Law
 * Vol 1 is the only subject the two name differently, and a lookup that
 * understood only one of them either returned nothing or printed the raw id
 * next to a chapter title. */
function practiceCentreSubjectFor(id) {
    if (!id) return null;
    for (var i = 0; i < PRACTICE_CENTRE_SUBJECTS.length; i++) {
        if (PRACTICE_CENTRE_SUBJECTS[i].id === id) return PRACTICE_CENTRE_SUBJECTS[i];
    }
    for (var j = 0; j < PRACTICE_CENTRE_SUBJECTS.length; j++) {
        if (PRACTICE_CENTRE_SUBJECTS[j].bankIds.indexOf(id) !== -1) {
            return PRACTICE_CENTRE_SUBJECTS[j];
        }
    }
    return null;
}

/* Chapters of one subject, from the study text, in printed order.
 *
 * `id` is taken from the chapter when present and otherwise derived from its
 * first topic's id, because the chapter list and the question bank have to agree
 * on what a chapter is called or every count comes back zero. */
function practiceCentreChapters(subjectId) {
    const store = (typeof mmDataStore !== 'undefined' && mmDataStore) ? mmDataStore : {};
    const rows = store[subjectId] || [];
    const out = [];
    rows.forEach(function (c, i) {
        const topics = c.topics || [];
        const first = topics[0] || {};
        const id = c.id || String(first.id || '').replace(/-t\d+$/, '');
        if (!id) return;
        out.push({
            id: id,
            number: (c.chapterNumber === undefined ? i + 1 : c.chapterNumber),
            title: c.title || ''
        });
    });
    out.sort(function (a, b) { return a.number - b.number; });
    return out;
}

/* --------------------------------------------------------- chapter focus sets
 *
 * ICAP does not examine the eight CAF subjects the same way, and a candidate
 * revising for one of them wants the kind of question that subject actually
 * sets. These are the three slices, offered in the Question source selector
 * beside "All generated practice".
 *
 * RECALL is excluded from all three, deliberately. The bank also holds recall
 * prompts, and a source called "Numerical focus" that answered "Define primary
 * data" five times would be worse than no source at all. Those questions stay
 * reachable through "All generated practice".
 *
 * `verify_caf_focus.py` reads this table back out of the page and asserts it
 * against `_build/pipeline/caf_focus_bank.SUBJECT_FOCUS` - the table that
 * GENERATES these questions - so a focus set can never name a subject/type pair
 * that does not exist, or miss one that does. */
const PRACTICE_CENTRE_FOCUS = [
    {
        id: 'FOCUS_NUMERICAL',
        short: 'numerical',
        label: 'Chapter-wise numerical - CAF-1, CAF-2, CAF-5, CAF-6',
        subjects: ['caf1', 'caf2', 'caf5', 'caf6'],
        types: ['NUMERICAL'],
        note: 'Every question carries figures, a working and an answer computed '
            + 'from those same figures. Where the chapter has a registered '
            + 'computation the stem, the workings and the answer are rendered '
            + 'from one figure set and cannot disagree.'
    },
    {
        id: 'FOCUS_SCENARIO',
        short: 'scenario',
        label: 'Chapter-wise scenario - CAF-3, CAF-4, CAF-8',
        /* `caf4` is Business Law Vol I and `caf4v2` Vol II. They are two rows
         * here because the study text is split, and both are Business Law, so
         * scenario focus covers both volumes - 43 questions instead of the 53 a
         * single `caf4` row would suggest, and all 10 of Vol I's included. */
        subjects: ['caf3', 'caf4', 'caf4v2', 'caf8'],
        types: ['SCENARIO'],
        note: 'Every question puts you inside a named company - invented for '
            + 'practice, and never presented as an ICAP question - with three '
            + 'parts and a model answer. These subjects are examined on '
            + 'application and reasoning, not on arithmetic.'
    },
    {
        id: 'FOCUS_MIXED',
        short: 'numerical and scenario',
        label: 'Chapter-wise numerical and scenario - CAF-2, CAF-7',
        subjects: ['caf2', 'caf7'],
        types: ['NUMERICAL', 'SCENARIO'],
        note: 'Both written types together, in the two subjects ICAP examines '
            + 'with a genuine mix. A session here alternates between a '
            + 'computation and a case rather than being all of one.'
    }
];

function practiceCentreFocusById(id) {
    if (!id) return null;
    for (var i = 0; i < PRACTICE_CENTRE_FOCUS.length; i++) {
        if (PRACTICE_CENTRE_FOCUS[i].id === id) return PRACTICE_CENTRE_FOCUS[i];
    }
    return null;
}

/* The generated questions a focus set actually draws on. Page ids are expanded
 * through `bankIds` first, so naming `caf4v1` reaches the bank's `caf4` rows
 * rather than matching nothing. */
function practiceCentreFocusPool(focus) {
    const bank = practiceIndexBank();
    if (!bank || !focus) return [];
    const want = {};
    focus.subjects.forEach(function (s) {
        const row = practiceCentreSubjectFor(s);
        (row ? row.bankIds : [s]).forEach(function (b) { want[b] = true; });
    });
    return (bank.generated || []).filter(function (q) {
        return !!want[q.subjectId] && focus.types.indexOf(q.type) !== -1;
    });
}

/* Where a subject's app name and its papers' own name differ. Surfaced, not
 * resolved: see the note above.
 *
 * Punctuation and the ampersand are not differences. The app writes "&" and the
 * papers write "and", so "Financial Accounting & Reporting" against "Financial
 * Accounting and Reporting" is the same name and reporting it as a conflict would
 * bury the one that matters. "&" is folded to "and" before comparing.
 *
 * What survives that fold is worth knowing about, and the differing words are named
 * rather than left for the reader to diff:
 *
 *   caf4  Business Law Dynamics - Vol I   vs  Business Law Dynamics
 *         the app splits a two-volume subject into one row per volume, and the
 *         papers are named for the subject. Expected.
 *   caf6  Managerial & Financial Analysis vs  Corporate Reporting
 *         DIFFERENT SUBJECTS. The app's name comes from CAF-6-ST.pdf; both supplied
 *         CAF-6 papers print "Corporate Reporting" on their cover.
 *   caf7  Business Information Analysis  vs  Business Insights and Analysis
 *         the app's name appears to be a transposition; "Insights" is ICAP's usage.
 *   caf8  Audit & Assurance               vs  Audit and Assurance Essentials
 *         the app's name is a short form of the papers'.
 */
function practiceCentreNameKey(text) {
    return String(text == null ? '' : text)
        .toLowerCase()
        .replace(/&/g, ' and ')
        .replace(/[^a-z0-9]+/g, '');
}

const practiceCentreNameConflicts = PRACTICE_CENTRE_SUBJECTS
    .filter(function (s) {
        if (!s.corpusName) return false;
        return practiceCentreNameKey(s.corpusName) !== practiceCentreNameKey(s.appName);
    })
    .map(function (s) {
        function words(t) {
            return String(t).toLowerCase().replace(/&/g, ' and ')
                .split(/[^a-z0-9]+/).filter(Boolean);
        }
        var app = words(s.appName), cor = words(s.corpusName);
        var onlyApp = app.filter(function (w) { return cor.indexOf(w) < 0; });
        var onlyCor = cor.filter(function (w) { return app.indexOf(w) < 0; });
        return {
            id: s.id,
            appName: s.appName,
            corpusName: s.corpusName,
            onlyInAppName: onlyApp,
            onlyInPapersName: onlyCor
        };
    });

const PRACTICE_CENTRE_DIFFICULTIES = [
    { id: '', label: 'Any difficulty' },
    { id: 'FOUNDATION', label: 'Foundation' },
    { id: 'APPLICATION', label: 'Application' },
    { id: 'ADVANCED', label: 'Advanced' },
    { id: 'EXAM_LEVEL', label: 'Exam level' }
];

let PRACTICE_CENTRE = {
    session: null,
    questions: [],
    index: 0,
    answers: {},
    lastResult: null,
    overlayOpen: false
};

function practiceCentreEscape(s) {
    return String(s === undefined || s === null ? '' : s)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

/* ------------------------------------------------------------------ launcher */

function initPracticeCentre() {
    if (document.getElementById(PRACTICE_CENTRE_LAUNCHER_ID)) return;
    const host = document.getElementById('practice-main-container');
    if (!host) return;
    const box = document.createElement('div');
    box.id = PRACTICE_CENTRE_LAUNCHER_ID;
    box.className = 'pc-launcher';
    box.innerHTML =
        '<div class="pc-launcher-inner">' +
        '  <div>' +
        '    <div class="pc-launcher-title">Written Practice Centre</div>' +
        '    <div class="pc-launcher-sub">Handwritten or typed answers, marked ' +
        '      criterion by criterion against the CAF study text. ' +
        '      Practice questions are generated, not official ICAP questions.</div>' +
        '  </div>' +
        '  <button type="button" class="pc-btn pc-btn-primary" id="pc-open-btn">' +
        '    Open Practice Centre</button>' +
        '</div>';
    host.parentNode.insertBefore(box, host);
    box.querySelector('#pc-open-btn').addEventListener('click', function () {
        practiceCentreOpen();
    });
}

/* ------------------------------------------------------------------- overlay */

function practiceCentreOverlay() {
    let ov = document.getElementById(PRACTICE_CENTRE_OVERLAY_ID);
    if (ov) return ov;
    ov = document.createElement('div');
    ov.id = PRACTICE_CENTRE_OVERLAY_ID;
    ov.className = 'pc-overlay';
    ov.setAttribute('role', 'dialog');
    ov.setAttribute('aria-modal', 'true');
    ov.addEventListener('click', function (e) {
        if (e.target === ov) practiceCentreClose();
    });
    document.body.appendChild(ov);
    return ov;
}

function practiceCentreClose() {
    const ov = document.getElementById(PRACTICE_CENTRE_OVERLAY_ID);
    if (ov) ov.classList.remove('pc-open');
    PRACTICE_CENTRE.overlayOpen = false;
}

function practiceCentreOpen() {
    practiceCentreOverlay().classList.add('pc-open');
    PRACTICE_CENTRE.overlayOpen = true;
    practiceCentreRenderSetup();
}

function practiceCentrePanel(html) {
    const ov = practiceCentreOverlay();
    let panel = ov.querySelector('.pc-panel');
    if (!panel) {
        panel = document.createElement('div');
        panel.className = 'pc-panel';
        ov.appendChild(panel);
    }
    panel.innerHTML =
        '<button type="button" class="pc-close" id="pc-close" aria-label="Close">&#10005;</button>'
        + html;
    panel.querySelector('#pc-close').addEventListener('click', practiceCentreClose);
    return panel;
}

function practiceCentreHeader(subtitle) {
    const provider = getOCRProvider();
    return '<div class="pc-head">' +
        '<div class="pc-head-title">CAF Written Practice Centre</div>' +
        '<div class="pc-head-sub">' + practiceCentreEscape(subtitle || '') + '</div>' +
        '<div class="pc-head-ocr">Answer input: <strong>' +
        practiceCentreEscape(provider.describe()) + '</strong></div>' +
        '</div>';
}

/* --------------------------------------------------------------- setup screen */

function practiceCentreRenderSetup() {
    const bank = practiceIndexBank();
    if (!bank) {
        practiceCentrePanel(practiceCentreHeader('Bank unavailable') +
            '<p class="pc-note">The practice bank did not load.</p>');
        return;
    }
    const available = {};
    /* Per-subject counts for the Subject dropdown and for the note under it.
     *
     * These must be read for the SELECTED source, not for the bank as a whole.
     * "CAF-1 (64)" beside a source called "Numerical focus" would promise 64
     * numerical questions out of the 13 that exist - so the count comes from the
     * same pool the session will be drawn from. Alias-aware, so CAF-4 Vol 1
     * counts the bank's `caf4` rows instead of showing "- none yet". */
    /* One pool, one count. This used to branch on the focus source and fall back
     * to `bank.bySubject`, which is a THIRD way of counting the same questions -
     * three is one too many. `practiceSelectPool` is what the draw uses, so
     * asking it is the only way the numbers can be right. */
    function countsForSource(kind) {
        const bySubj = {};
        practiceSelectPool({ kind: kind }).forEach(function (q) {
            bySubj[q.subjectId] = (bySubj[q.subjectId] || 0) + 1;
        });
        return bySubj;
    }

    const allCounts = countsForSource('GENERATED_PRACTICE');
    Object.keys(allCounts).forEach(function (s) { available[s] = allCounts[s]; });

    /* Official questions are counted per subject from the official pool directly,
     * not from `bank.bySubject`. That index is built over the generated questions
     * only, so reusing it would have shown the generated count beside an
     * "Official past-paper questions" label - the same number twice, for two
     * different sets of questions. */
    const officialBySubject = {};
    (bank.official || []).forEach(function (q) {
        officialBySubject[q.subjectId] = (officialBySubject[q.subjectId] || 0) + 1;
    });

    /* The Subject rows for a source, as data.
     *
     * ALL subjects stay listed under every source. A focus set used to hide the
     * subjects it did not cover, which read as the app having lost five of the
     * nine volumes - and switching source silently moved the candidate to a
     * different subject. A subject with no questions under the current source is
     * shown disabled and marked "- none", so the full set is always visible and
     * the emptiness is stated rather than concealed.
     *
     * Counts come from the same pool the session is drawn from (practiceSelectPool),
     * so the number beside a subject and the questions that arrive cannot disagree.
     * Alias-aware, so CAF-4 Vol 1 counts the bank's `caf4` rows. */
    function subjectRowsFor(kind) {
        const counts = {};
        practiceSelectPool({ kind: kind }).forEach(function (q) {
            counts[q.subjectId] = (counts[q.subjectId] || 0) + 1;
        });
        return PRACTICE_CENTRE_SUBJECTS.map(function (s) {
            let n = 0;
            s.bankIds.forEach(function (b) { n += counts[b] || 0; });
            return { value: s.id, label: s.label, n: n };
        });
    }

    function subjectOptionsFor(kind) {
        return subjectRowsFor(kind).map(function (r) {
            return '<option value="' + r.value + '"' + (r.n ? '' : ' disabled') + '>' +
                practiceCentreEscape(r.label) + (r.n ? ' (' + r.n + ')' : ' - none') + '</option>';
        }).join('');
    }

    /* Chapters for the chosen subject, from the study text, with counts from the
     * current pool. Derived from `topicId` (`<subject>-ch<N>-t<M>`) rather than a
     * stored chapterId, because the runtime bank row does not carry one.
     *
     * Returns [] when no subject is chosen: a chapter list across all nine
     * volumes would be 128 rows and would read as a subject list in disguise. */
    function chapterRowsFor(kind, subjectId) {
        if (!subjectId) return [];
        const counts = {};
        practiceSelectPool({ kind: kind, subjectId: subjectId })
            .forEach(function (q) {
                const c = practiceChapterId(q);
                if (c) counts[c] = (counts[c] || 0) + 1;
            });
        return practiceCentreChapters(subjectId).map(function (c) {
            return {
                value: c.id,
                label: 'Chapter ' + c.number + ' - ' + c.title,
                n: counts[c.id] || 0
            };
        });
    }

    function chapterOptionsFor(kind, subjectId) {
        const rows = chapterRowsFor(kind, subjectId);
        if (!subjectId) {
            return '<option value="">Choose a subject first</option>';
        }
        const total = rows.reduce(function (t, r) { return t + r.n; }, 0);
        return '<option value="">All chapters</option>' + rows.map(function (r) {
            return '<option value="' + r.value + '"' + (r.n ? '' : ' disabled') + '>' +
                practiceCentreEscape(r.label) + (r.n ? ' (' + r.n + ')' : ' - none') + '</option>';
        }).join('') + (total ? '' : '');
    }

    const subjectOptions = subjectOptionsFor('GENERATED_PACTICE');
    const chapterOptions = chapterOptionsFor('GENERATED_PACTICE', '');

    const diffOptions = PRACTICE_CENTRE_DIFFICULTIES.map(function (d) {
        return '<option value="' + d.id + '">' + practiceCentreEscape(d.label) + '</option>';
    }).join('');

    // A source selector, because the three kinds are marked by different engines
    // and a candidate should not have to call `practiceSelectQuestions` from the
    // console to reach the official past-paper questions. The note below used to
    // say those questions "can be marked in past-paper mode from the API" - which
    // described a capability while giving no route to it, for 61 questions that
    // are the only ones in the bank with an examiner's own mark scheme attached.
    //
    // OFFICIAL is listed with its count and is disabled when the selected subject has
    // none. Of the 35 supplied papers only 7 could be paired with an answer key
    // exactly and 2 with a numbering mismatch, so most subjects have few or none -
    // showing it as available everywhere would be a promise the bank cannot keep.
    //
    // GENERATED_PAPER is a whole 100-mark paper in paper order, with the paper's
    // own rubric, so difficulty and question count do not apply to it - the paper
    // decides both - and the controls say so by being disabled rather than by
    // being ignored.
    const paperList = bank.paperList || [];

    /* The three focus sets are CHAPTER-WISE slices of generated practice, so
     * they are nested inside an <optgroup> headed by it rather than listed as
     * siblings. As siblings they read as four unrelated sources, and choosing
     * "numerical focus" looked like leaving generated practice altogether.
     *
     * Each option carries its own live count, taken from the same pool the
     * session is drawn from, so a disabled option can never be a promise the
     * bank cannot keep. */
    function kindOptionRow(k) {
        return '<option value="' + k.id + '"' + (k.n ? '' : ' disabled') + '>' +
            practiceCentreEscape(k.label) + (k.n ? ' (' + k.n + ')' : ' - none') + '</option>';
    }

    const focusKindOptions = PRACTICE_CENTRE_FOCUS.map(function (f) {
        return kindOptionRow({
            id: f.id, label: f.label, n: practiceCentreFocusPool(f).length
        });
    }).join('');

    const kindOptions =
        '<optgroup label="Generated practice (from the CAF study text)">'
        + kindOptionRow({
            id: 'GENERATED_PRACTICE',
            label: 'All chapters - numerical, scenario and recall',
            n: bank.generated.length
        })
        + focusKindOptions
        + '</optgroup>'
        + kindOptionRow({
            id: 'OFFICIAL_PAST_PAPER',
            label: 'Official past-paper questions (marked against ICAP suggested answers)',
            n: bank.official.length
        })
        + kindOptionRow({
            id: 'GENERATED_PAPER',
            label: 'Full generated paper (100-mark paper in paper order)',
            n: paperList.length
        });

    practiceCentrePanel(practiceCentreHeader(
        bank.generated.length + ' generated practice questions, '
        + bank.official.length + ' official past-paper questions and '
        + paperList.length + ' full generated papers, across '
        + Object.keys(available).length + ' CAF subjects') +
        '<div class="pc-setup">' +
        '  <label class="pc-field pc-field-wide"><span>Question source</span>' +
        '    <select id="pc-kind">' + kindOptions + '</select></label>' +
        '  <label class="pc-field"><span>Subject</span>' +
        '    <select id="pc-subject">' + subjectOptions + '</select></label>' +
        '  <label class="pc-field"><span>Chapter</span>' +
        '    <select id="pc-chapter">' + chapterOptions + '</select></label>' +
        '  <label class="pc-field"><span>Paper</span>' +
        '    <select id="pc-paper" disabled><option value="">Choose a source first</option></select></label>' +
        '  <label class="pc-field"><span>Difficulty</span>' +
        '    <select id="pc-difficulty">' + diffOptions + '</select></label>' +
        '  <label class="pc-field"><span>Questions</span>' +
        '    <select id="pc-count">' +
        '      <option value="3">3</option><option value="5" selected>5</option>' +
        '      <option value="10">10</option><option value="15">15</option>' +
        '    </select></label>' +
        '  <button type="button" class="pc-btn pc-btn-primary" id="pc-start">Start session</button>' +
        '</div>' +
        '<div class="pc-note" id="pc-kind-note"></div>' +
        '<div class="pc-note">' +
        '  Generated questions and generated papers are <strong>practice</strong>, built ' +
        '  from the CAF study text and shaped by patterns measured in real ICAP past ' +
        '  papers. They are not ICAP questions and are never presented as such. Official ' +
        '  past-paper questions are reproduced from the supplied papers and marked ' +
        '  against the examiner\'s own suggested answer, with no partial credit on ' +
        '  multiple-choice items.' +
        '</div>' +
        (practiceCentreLoadSessions().length
            ? '<div class="pc-note">' +
              '<button type="button" class="pc-btn pc-btn-primary" id="pc-weak">' +
              'Where am I weak?</button> ' +
              '<button type="button" class="pc-btn" id="pc-analytics">' +
              'Progress &amp; analytics</button> ' +
              '<button type="button" class="pc-btn" id="pc-mb">' +
              'View mistake book</button></div>'
            : '') +
        '<div class="pc-note"><button type="button" class="pc-btn pc-btn-quiet" id="pc-review">' +
        'Content review &amp; approval (admin)</button> ' +
        '<span class="pc-quiet">The build-time pipeline record re-checked against ' +
        'the bank loaded in this page; sign-off is exported as a file.</span></div>');

    const panel = document.querySelector('.pc-panel');
    const kindSel = panel.querySelector('#pc-kind');
    const subjSel = panel.querySelector('#pc-subject');
    const chapSel = panel.querySelector('#pc-chapter');
    const diffSel = panel.querySelector('#pc-difficulty');
    const countSel = panel.querySelector('#pc-count');
    const paperSel = panel.querySelector('#pc-paper');
    const startBtn = panel.querySelector('#pc-start');

    /* The difficulty tiers are a property of the generated questions. Official
     * questions carry the paper's own difficulty, which is not on one of these four
     * scales, so the control is disabled and says why rather than silently returning
     * every question when a tier is chosen. A full paper disables it for a simpler
     * reason: the paper's questions are fixed, so difficulty and count are the
     * paper's decisions, not the candidate's. */
    function papersForSubject() {
        return (bank.paperList || []).filter(function (p) {
            return !subjSel.value || p.subject === subjSel.value;
        });
    }

    function syncKind() {
        const official = kindSel.value === 'OFFICIAL_PAST_PAPER';
        const paper = kindSel.value === 'GENERATED_PAPER';
        diffSel.disabled = official || paper;
        if (official || paper) diffSel.value = '';
        countSel.disabled = paper;
        paperSel.disabled = !paper;

        /* Rebuild the subject list for this source, keeping the candidate's
         * subject. Every subject is listed under every source now, so the only
         * question is whether the one they chose is still there - and it is.
         *
         * It used to fall back to "the first subject with questions", which
         * quietly MOVED them: picking "scenario focus" while on CAF-1 switched
         * the subject to CAF-3. Better to leave them on CAF-1 showing zero and
         * say which subjects do have questions, than to answer a different
         * question than the one they set up.
         *
         * The candidate's CHAPTER is reset with the source, because a chapter id
         * means nothing under a source that no longer offers its subject - and a
         * stale chapter is how a session silently comes back empty.
         *
         * The fallback comes from the rows just built, not from reading
         * `select.options` back: the rendered HTML is the one thing known to
         * agree with what was set, and re-reading the DOM is a second source of
         * truth that can disagree with it. */
        const hadSubject = subjSel.value;
        const rows = subjectRowsFor(kindSel.value);
        const freshSubjects = subjectOptionsFor(kindSel.value);
        if (subjSel.innerHTML !== freshSubjects) {
            subjSel.innerHTML = freshSubjects;
            const present = rows.map(function (r) { return r.value; });
            const usable = rows.filter(function (r) { return r.n; })
                .map(function (r) { return r.value; });
            subjSel.value = (present.indexOf(hadSubject) !== -1) ? hadSubject
                : (usable[0] || '');
        }

        /* Chapter list, for the subject now chosen. Disabled where a chapter
         * cannot mean anything: a full paper is a fixed sequence, and none of
         * the 61 official past-paper questions carries a study-text topicId, so
         * a chapter filter there would match nothing. Said, not silently empty. */
        const chapterSupported = !paper && !official;
        chapSel.innerHTML = chapterSupported
            ? chapterOptionsFor(kindSel.value, subjSel.value)
            : (paper
                ? '<option value="">Not applicable to a full paper</option>'
                : '<option value="">Official questions are not tied to a chapter</option>');
        chapSel.disabled = !chapterSupported || !subjSel.value;
        if (!chapSel.value || !practiceChapterRowUsable(kindSel.value, subjSel.value, chapSel.value)) {
            chapSel.value = '';
        }

        const list = papersForSubject();
        paperSel.innerHTML = list.length
            ? list.map(function (p) {
                return '<option value="' + p.paperId + '">' +
                    practiceCentreEscape('Paper ' + p.paperId.split('-').pop()
                        + ' - ' + p.focus.toLowerCase() + ' focus, ' + p.totalMarks
                        + ' marks, ' + p.questions.length + ' written questions') +
                    '</option>';
            }).join('')
            : '<option value="">No paper for this subject yet</option>';

        const note = panel.querySelector('#pc-kind-note');
        if (paper) {
            startBtn.disabled = !list.length;
            note.innerHTML = list.length
                ? '<strong>' + list.length + ' paper' + (list.length === 1 ? '' : 's')
                  + '</strong> for this subject, taken in paper order and marked '
                  + 'against the rubric the paper was designed with. Its Section A '
                  + 'is declared on the overview but is not answerable here - the '
                  + 'item text was not recoverable, and inventing it would be worse.'
                : 'No generated paper for this subject yet. Use generated practice '
                  + 'questions, or pick another subject.';
            return;
        }

        /* A focus source. The note says what the pool actually contains, and the
         * button is disabled when it is empty rather than starting a session that
         * would immediately report nothing was selected. */
        const focus = practiceCentreFocusById(kindSel.value);
        if (focus) {
            const n = practiceSelectPool({
                kind: kindSel.value, subjectId: subjSel.value, chapterId: chapSel.value
            }).length;
            const scope = chapSel.value ? 'this chapter'
                : (subjSel.value ? 'this subject' : 'these subjects');
            startBtn.disabled = !n;
            note.innerHTML = '<strong>' + n + ' ' + practiceCentreEscape(focus.short)
                + ' question' + (n === 1 ? '' : 's') + '</strong> for '
                + scope + '. ' + practiceCentreEscape(focus.note)
                /* Zero is a dead end unless it says where the questions are.
                 * Without this the candidate is left staring at a disabled
                 * button on a subject they chose themselves. */
                + (n ? '' : ' Nothing matches here - the subjects with '
                    + practiceCentreEscape(focus.short) + ' questions are '
                    + practiceCentreEscape(focusSubjectList(kindSel.value)) + '.');
            return;
        }

        /* Every count on this screen comes from `practiceSelectPool`, the same
         * function the draw uses, so the number in the note and the questions
         * that arrive cannot disagree. */
        const n = practiceSelectPool({
            kind: kindSel.value, subjectId: subjSel.value, chapterId: chapSel.value
        }).length;
        startBtn.disabled = !n;
        const scope = chapSel.value ? 'this chapter'
            : (subjSel.value ? 'this subject' : 'these subjects');
        note.innerHTML = official
            ? '<strong>' + n + ' official question' + (n === 1 ? '' : 's')
              + '</strong> for ' + scope + '. Only papers supplied with an ICAP '
              + 'suggested answer can be marked against the examiner\'s own scheme; '
              + 'the rest are absent from this list rather than shown without a mark scheme.'
            : '<strong>' + n + ' generated question' + (n === 1 ? '' : 's')
              + '</strong> for ' + scope + '. Marked against a criteria-based rubric.';
    }

    /* Which subjects a source can actually answer, by their short names, for the
     * "nothing here - try these" line. Read from the same rows the Subject
     * dropdown shows, so the hint cannot name a subject the list lacks. */
    function focusSubjectList(kind) {
        const names = [];
        subjectRowsFor(kind).forEach(function (r) {
            if (r.n) names.push(r.label.replace(/^CAF-\d+\s*/, '').split(' - ')[0]);
        });
        return names.length ? names.join(', ') : 'none yet';
    }

    /* Does this chapter still have questions under the current source? Used to
     * clear a chapter that the new source cannot satisfy. */
    function practiceChapterRowUsable(kind, subjectId, chapterId) {
        if (!chapterId) return true;
        return chapterRowsFor(kind, subjectId)
            .some(function (r) { return r.value === chapterId && r.n > 0; });
    }
    kindSel.addEventListener('change', syncKind);
    subjSel.addEventListener('change', syncKind);
    /* The chapter control re-runs syncKind rather than only refreshing the note:
     * the subject is left alone here, so the list must not be rebuilt (that would
     * discard the chapter), but the note and the button both depend on it. */
    chapSel.addEventListener('change', function () {
        const note = panel.querySelector('#pc-kind-note');
        const focus = practiceCentreFocusById(kindSel.value);
        const n = practiceSelectPool({
            kind: kindSel.value, subjectId: subjSel.value, chapterId: chapSel.value
        }).length;
        startBtn.disabled = !n;
        const scope = chapSel.value ? 'this chapter'
            : (subjSel.value ? 'this subject' : 'these subjects');
        const heading = focus
            ? '<strong>' + n + ' ' + practiceCentreEscape(focus.short) + ' question'
                + (n === 1 ? '' : 's') + '</strong> for ' + scope + '. '
                + practiceCentreEscape(focus.note)
            : '<strong>' + n + ' generated question' + (n === 1 ? '' : 's')
                + '</strong> for ' + scope + '. Marked against a criteria-based rubric.';
        note.innerHTML = heading;
    });
    syncKind();

    startBtn.addEventListener('click', function () {
        if (kindSel.value === 'GENERATED_PAPER') {
            if (paperSel.value) practiceCentreRenderPaperOverview(paperSel.value);
            return;
        }
        practiceCentreStartSession({
            kind: kindSel.value,
            subjectId: subjSel.value,
            chapterId: chapSel.value || null,
            difficulty: diffSel.value || null,
            count: parseInt(countSel.value, 10) || 5
        });
    });
    const mbBtn = panel.querySelector('#pc-mb');
    if (mbBtn) {
        mbBtn.addEventListener('click', function () {
            practiceCentreRenderMistakeBook();
        });
    }
    const weakBtn = panel.querySelector('#pc-weak');
    if (weakBtn) {
        weakBtn.addEventListener('click', function () {
            practiceCentreRenderWeakness();
        });
    }
    const analyticsBtn = panel.querySelector('#pc-analytics');
    if (analyticsBtn) {
        analyticsBtn.addEventListener('click', function () {
            practiceCentreRenderAnalytics();
        });
    }
    const reviewBtn = panel.querySelector('#pc-review');
    if (reviewBtn) {
        reviewBtn.addEventListener('click', function () {
            practiceCentreRenderReview();
        });
    }
}

function practiceCentreStartSession(opts) {
    /* `questions` lets a recommendation start a session the form cannot express
     * - the handful a weak topic has left, unattempted - while every other
     * route still goes through the same selection. */
    const questions = (opts.questions && opts.questions.length)
        ? opts.questions
        : practiceSelectQuestions(opts);
    if (!questions.length) {
        practiceCentrePanel(practiceCentreHeader('Nothing selected') +
            '<p class="pc-note">No questions match that combination. Try another subject or difficulty.</p>');
        return;
    }
    PRACTICE_CENTRE.questions = questions;
    PRACTICE_CENTRE.index = 0;
    PRACTICE_CENTRE.answers = {};
    PRACTICE_CENTRE.lastResult = null;
    // `kind` comes from the source selector rather than being hardcoded, so an
    // official session is recorded as official. Hardcoding it here meant every
    // session was labelled GENERATED_PRACTICE while the question inside it was an
    // official past-paper question - so the mistake book, the analytics and any
    // export all attributed ICAP questions to the generator.
    // A focus session says which focus it was, so a mixed CAF-2/CAF-7 record is
    // legible in the history instead of looking like undifferentiated practice.
    const focus = practiceCentreFocusById(opts.kind);
    const sessionLabel = opts.kind === 'OFFICIAL_PAST_PAPER'
        ? 'CAF past-paper practice'
        : (focus ? ('CAF practice - ' + focus.short + ' focus') : 'CAF written practice');
    PRACTICE_CENTRE.session = practiceCreateSession({
        questions: questions,
        subjectId: opts.subjectId,
        label: sessionLabel,
        kind: opts.kind || 'GENERATED_PRACTICE'
    });
    practiceCentreRenderQuestion();
}

/* --------------------------------------------------------- paper overview
 * A paper is not a bag of questions. It has a total, a duration, a design mix
 * and a Section A this build cannot serve, and all four are shown before the
 * candidate commits to it: starting a "100-mark paper" that can only award 90
 * has to be said on the screen, not discovered at the end of it. So does what
 * the paper IS - generated practice, not an ICAP paper - which is stated in the
 * paper's own provenance line rather than in a footnote of ours.
 */
function practiceCentreRenderPaperOverview(paperId) {
    const bank = practiceIndexBank();
    const p = bank && bank.paperById ? bank.paperById[paperId] : null;
    if (!p) { practiceCentreRenderSetup(); return; }

    const subject = practiceCentreSubjectFor(p.subject);
    const subjectLabel = subject ? subject.label : (p.subjectName || p.subject);
    const secA = p.sectionA || {};
    const prov = p.provenance || {};

    const qrows = p.questions.map(function (q) {
        return '<tr><td class="pc-num">' + q.number + '</td>' +
            '<td>' + practiceCentreEscape(q.section || '-') + '</td>' +
            '<td>' + practiceCentreEscape(q.type) + '</td>' +
            '<td class="pc-num">' + q.marks + '</td></tr>';
    }).join('');

    /* Designed, achieved and measured side by side. This is the paper's answer
     * to "why is this paper mostly numbers?" - the design mix was set from what
     * this subject's real papers measure, and the achieved column is what this
     * paper actually came out at. */
    const basis = p.designBasis || {};
    const design = basis.designMix || {};
    const measured = basis.measuredMix || {};
    const achieved = (p.achieved && p.achieved.marksShareByType) || {};
    const types = Object.keys(achieved).concat(
        Object.keys(design).filter(function (t) {
            return Object.keys(achieved).indexOf(t) === -1;
        }));
    const mixrows = types.map(function (t) {
        function pct(m) { return m[t] === undefined ? '-' : m[t] + '%'; }
        return '<tr><td>' + practiceCentreEscape(t) + '</td>' +
            '<td class="pc-num">' + pct(design) + '</td>' +
            '<td class="pc-num">' + pct(achieved) + '</td>' +
            '<td class="pc-num">' + pct(measured) + '</td></tr>';
    }).join('');

    const secABox = secA.itemsAvailable
        ? '<div class="pc-note"><strong>Section ' +
          practiceCentreEscape(secA.section || 'A') + ':</strong> ' +
          practiceCentreEscape(String(secA.marks)) + ' marks of objective items.</div>'
        : '<div class="pc-warnbox"><strong>Section ' +
          practiceCentreEscape(secA.section || 'A') + ' is declared at ' +
          practiceCentreEscape(String(secA.marks)) + ' marks but cannot be sat here.</strong> ' +
          practiceCentreEscape(secA.reason || 'Its items were not recoverable.') +
          ' The written section below is what this session will mark.</div>';

    const aligned = p.questions.filter(function (q) {
        return q.requirementFromTopic;
    }).length;
    const traceLine = aligned
        ? '<strong>' + aligned + ' of ' + p.questions.length + '</strong> questions take '
          + 'their requirement from a named study-text topic; the rest are filed under a '
          + 'topic while their figures are composed for practice. The topic is shown with '
          + 'each marked answer, and which of the two it is.'
        : 'No question in this paper draws its requirement from a named study-text topic.';

    practiceCentrePanel(practiceCentreHeader(subjectLabel + ' - generated paper ' + p.paperId) +
        '<div class="pc-progress">' +
        '  <span class="pc-badge">' + practiceCentreEscape(p.focus || '') + ' focus</span>' +
        '  <span class="pc-badge">' + p.totalMarks + ' marks</span>' +
        '  <span class="pc-badge">' + (p.durationHours || '-') + ' hours</span>' +
        '  <span class="pc-badge">' + p.questions.length + ' written questions (' +
              p.writtenMarks + ' marks)</span>' +
        '</div>' +
        '<div class="pc-question">' + practiceCentreEscape(p.instruction || '') + '</div>' +
        secABox +
        '<div class="pc-note">' + practiceCentreEscape(
            prov.statement || 'Generated practice paper.') + '</div>' +
        '<h4 class="pc-h">Where the marks sit</h4>' +
        '<table class="pc-criteria"><thead><tr><th>Type</th><th>Designed</th>' +
        '<th>This paper</th><th>Measured in real papers</th></tr></thead><tbody>' +
        mixrows + '</tbody></table>' +
        '<h4 class="pc-h">Written section</h4>' +
        '<table class="pc-criteria"><thead><tr><th>Q</th><th>Section</th><th>Type</th>' +
        '<th>Marks</th></tr></thead><tbody>' + qrows + '</tbody></table>' +
        '<div class="pc-note">' + traceLine + '</div>' +
        '<div class="pc-actions">' +
        '  <button type="button" class="pc-btn" id="pc-paper-back">Back</button>' +
        '  <button type="button" class="pc-btn pc-btn-primary" id="pc-paper-start">' +
        '    Start paper</button>' +
        '</div>' +
        '<div class="pc-note">Your expected answer and the paper\'s model workings are ' +
        'hidden until you submit each question.</div>');

    const panel = document.querySelector('.pc-panel');
    panel.querySelector('#pc-paper-back').addEventListener('click',
        practiceCentreRenderSetup);
    panel.querySelector('#pc-paper-start').addEventListener('click', function () {
        practiceCentreStartPaper(paperId);
    });
}

/* Start a paper: its own questions, in the paper's own order, as one session. */
function practiceCentreStartPaper(paperId) {
    const bank = practiceIndexBank();
    const p = bank && bank.paperById ? bank.paperById[paperId] : null;
    const questions = p ? bank.paperQuestions.filter(function (q) {
        return q.paperId === paperId;
    }) : [];
    if (!p || !questions.length) { practiceCentreRenderSetup(); return; }

    const subject = practiceCentreSubjectFor(p.subject);
    PRACTICE_CENTRE.questions = questions;
    PRACTICE_CENTRE.index = 0;
    PRACTICE_CENTRE.answers = {};
    PRACTICE_CENTRE.lastResult = null;
    PRACTICE_CENTRE.session = practiceCreateSession({
        questions: questions,
        subjectId: p.subject,
        paperId: paperId,
        label: (subject ? subject.label : p.subject) + ' - generated paper ' + paperId,
        kind: 'GENERATED_PAPER'
    });
    practiceCentreRenderQuestion();
}

/* ------------------------------------------------------------- question screen */

function practiceCentreRenderQuestion() {
    const C = PRACTICE_CENTRE;
    const q = C.questions[C.index];
    if (!q) { practiceCentreRenderSummary(); return; }

    // The attempt view is the ONLY question source used here. It carries no
    // expected answer, no rubric and no option letters.
    const view = practiceQuestionView(C.session, q.id);
    const saved = (C.answers[q.id] && C.answers[q.id].text) || '';
    const isObjective = view.isObjective;
    const progress = 'Question ' + (C.index + 1) + ' of ' + C.questions.length;

    const body = isObjective
        ? '<p class="pc-note">This is an official past-paper multiple-choice question. ' +
          'Select the option letters, then submit. It is marked exactly against the ' +
          'examiner\'s own answer key, with no partial credit.</p>' +
          '<div class="pc-mcq-grid" id="pc-mcq"></div>'
        : '<textarea id="pc-answer" class="pc-textarea" rows="12" ' +
          'placeholder="Type your answer here, or upload a photo of your handwritten answer below.">' +
          practiceCentreEscape(saved) + '</textarea>' +
          '<div class="pc-upload">' +
          '  <label class="pc-file">Upload handwritten answer' +
          '    <input type="file" id="pc-image" accept="image/*" capture="environment">' +
          '  </label>' +
          '  <button type="button" class="pc-btn" id="pc-ocr">Transcribe with OCR</button>' +
          '  <span class="pc-ocr-note" id="pc-ocr-note"></span>' +
          '</div>';

    practiceCentrePanel(practiceCentreHeader(view.sourceLabel) +
        '<div class="pc-progress">' + practiceCentreEscape(progress) +
        '  <span class="pc-badge">' + view.marks + ' mark' + (view.marks === 1 ? '' : 's') +
        '</span>' +
        (view.paperId
            ? '<span class="pc-badge">Section ' +
              practiceCentreEscape(view.paperSection || '-') + ' - Q' +
              practiceCentreEscape(String(view.paperQuestionNumber)) + '</span>'
            : '') +
        (view.difficulty ? '<span class="pc-badge">' + practiceCentreEscape(view.difficulty) + '</span>' : '') +
        (view.estimatedMinutes ? '<span class="pc-badge">~' + view.estimatedMinutes + ' min</span>' : '') +
        '</div>' +
        '<div class="pc-question">' + practiceCentreEscape(view.text) + '</div>' +
        body +
        '<div class="pc-actions">' +
        '  <button type="button" class="pc-btn" id="pc-prev"' +
            (C.index === 0 ? ' disabled' : '') + '>Previous</button>' +
        '  <button type="button" class="pc-btn pc-btn-primary" id="pc-submit">Submit answer</button>' +
        '  <button type="button" class="pc-btn" id="pc-next"' +
            (C.index >= C.questions.length - 1 ? ' disabled' : '') + '>Skip for now</button>' +
        '</div>' +
        '<div class="pc-note">Your expected answer is not shown while the session is live.</div>');

    const panel = document.querySelector('.pc-panel');

    if (isObjective) practiceCentreRenderMCQInputs(q);

    const submit = panel.querySelector('#pc-submit');
    if (submit) submit.addEventListener('click', function () { practiceCentreSubmit(); });
    const prev = panel.querySelector('#pc-prev');
    if (prev && !prev.disabled) {
        prev.addEventListener('click', function () {
            if (C.index > 0) { C.index -= 1; practiceCentreRenderQuestion(); }
        });
    }
    const next = panel.querySelector('#pc-next');
    if (next && !next.disabled) {
        next.addEventListener('click', function () {
            C.index += 1; practiceCentreRenderQuestion();
        });
    }

    const imgInput = panel.querySelector('#pc-image');
    const ocrBtn = panel.querySelector('#pc-ocr');
    if (ocrBtn && imgInput) {
        ocrBtn.addEventListener('click', function () {
            const file = imgInput.files && imgInput.files[0];
            const note = panel.querySelector('#pc-ocr-note');
            if (!file) {
                note.textContent = 'Choose a photo of your answer first.';
                note.className = 'pc-ocr-note pc-warn';
                return;
            }
            const provider = getOCRProvider();
            if (!provider.available) {
                note.textContent = 'No OCR endpoint configured. Type your answer instead.';
                note.className = 'pc-ocr-note pc-warn';
                return;
            }
            note.textContent = 'Transcribing...';
            note.className = 'pc-ocr-note';
            ocrBtn.disabled = true;
            const reader = new FileReader();
            reader.onload = function () {
                transcribeAnswer(reader.result).then(function (res) {
                    ocrBtn.disabled = false;
                    panel.querySelector('#pc-answer').value = res.text;
                    PRACTICE_CENTRE.answers[q.id] = res;
                    note.textContent = 'Transcribed (' + provider.name + '). '
                        + (res.confidence === null ? 'confidence not reported.'
                            : 'confidence ' + Math.round(res.confidence * 100) + '%.')
                        + (res.lowConfidence ? ' Low confidence - check it before submitting.' : '');
                    note.className = 'pc-ocr-note' + (res.lowConfidence ? ' pc-warn' : '');
                }).catch(function (err) {
                    ocrBtn.disabled = false;
                    note.textContent = 'OCR failed: ' + err.message;
                    note.className = 'pc-ocr-note pc-warn';
                });
            };
            reader.onerror = function () {
                ocrBtn.disabled = false;
                note.textContent = 'Could not read that image file.';
                note.className = 'pc-ocr-note pc-warn';
            };
            reader.readAsDataURL(file);
        });
    }
}

function practiceCentreRenderMCQInputs(q) {
    const grid = document.querySelector('#pc-mcq');
    if (!grid) return;

    // The view carries the item set for official Section A, or nothing for
    // generated practice MCQs. The two shapes are:
    //   official: mcqItems = [{item, marks, stem, a, textA, b, textB, ...}, ...]
    //   generated: mcqItems = undefined, fallback to single A/B/C/D grid.
    const view = practiceQuestionView(PRACTICE_CENTRE.session, q.id);
    const items = view && view.mcqItems;

    const saved = (PRACTICE_CENTRE.answers[q.id]
        && PRACTICE_CENTRE.answers[q.id].selectedOptions) || {};

    if (items && items.length) {
        // Section A: each item gets its own group of radio buttons.
        // The selectedOptions map is keyed by roman numeral ("i", "ii"...),
        // each value being the chosen option letter ("a".."d").
        const html = items.map(function (it) {
            const roman = it[0];
            const marks = it[1];
            const stem = it[2] || '';
            const opts = [];
            for (let k = 3; k < it.length; k += 2) {
                if (it[k]) opts.push([it[k], it[k + 1] || '']);
            }
            const sel = saved[roman] || '';
            return '<fieldset class="pc-mcq-item">' +
                '<legend>' + practiceCentreEscape(roman.toUpperCase()) +
                (marks ? ' <span class="pc-mcq-marks">[' + marks + ' mark' + (marks === 1 ? '' : 's') + ']</span>' : '') +
                '</legend>' +
                '<div class="pc-mcq-stem">' + practiceCentreEscape(stem) + '</div>' +
                '<div class="pc-mcq-options">' +
                opts.map(function (o) {
                    return '<label class="pc-mcq-cell">' +
                        '<input type="radio" name="pc-opt-' + roman + '" value="' + o[0] + '"' +
                        (sel === o[0] ? ' checked' : '') + '>' +
                        '<span>' + o[0].toUpperCase() + '</span> ' +
                        practiceCentreEscape(o[1]) + '</label>';
                }).join('') +
                '</div>' +
                '</fieldset>';
        }).join('');
        grid.innerHTML = html;
        return;
    }

    // Generated practice MCQ: single A/B/C/D grid keyed by a single letter.
    grid.innerHTML = ['', 'A', 'B', 'C', 'D'].map(function (letter) {
        return '<label class="pc-mcq-cell">' +
            '<input type="radio" name="pc-opt" value="' + letter + '"' +
            (saved[letter] === letter ? ' checked' : '') + '>' +
            '<span>' + letter + '</span></label>';
    }).join('');
}

/* ------------------------------------------------------------------- submit */

function practiceCentreSubmit() {
    const C = PRACTICE_CENTRE;
    const q = C.questions[C.index];
    if (!q) return;
    const view = practiceQuestionView(C.session, q.id);
    const panel = document.querySelector('.pc-panel');
    let transcription;

    if (view.isObjective) {
        const items = view.mcqItems;
        const chosen = {};
        if (items && items.length) {
            // Section A: each item has its own radio group named pc-opt-<roman>
            items.forEach(function (it) {
                const roman = it[0];
                const r = panel.querySelector('input[name="pc-opt-' + roman + '"]:checked');
                if (r) chosen[roman] = r.value;
            });
        } else {
            // Generated practice MCQ: single radio group named pc-opt
            panel.querySelectorAll('input[name="pc-opt"]:checked').forEach(function (r) {
                chosen[r.value] = r.value;
            });
        }
        transcription = { selectedOptions: chosen, rawText: '', text: '', confidence: 1 };
    } else {
        const ta = panel.querySelector('#pc-answer');
        const text = ta ? ta.value : '';
        const prior = C.answers[q.id] || {};
        if (!text.trim()) {
            const note = panel.querySelector('#pc-ocr-note');
            if (note) {
                note.textContent = 'Write or transcribe an answer before submitting.';
                note.className = 'pc-ocr-note pc-warn';
            }
            if (ta) ta.focus();
            return;
        }
        transcription = {
            rawText: text,
            text: practiceNormalize(text),
            // A typed answer is exact by definition; an OCR answer carries the
            // confidence it actually reported.
            confidence: prior.provider && !prior.manual ? prior.confidence : 1,
            provider: prior.provider || 'typed',
            manual: true,
            lowConfidence: prior.provider && !prior.manual ? !!prior.lowConfidence : false
        };
    }

    const result = practiceSubmit(C.session, q.id, transcription);
    C.answers[q.id] = transcription;
    C.lastResult = result;
    practiceCentreRenderFeedback();
}

/* ----------------------------------------------------------------- feedback */

function practiceCentreRenderFeedback() {
    const C = PRACTICE_CENTRE;
    const q = C.questions[C.index];
    const fb = practiceFeedback(C.session, q.id);
    if (!fb) { practiceCentreRenderQuestion(); return; }

    const criteriaRows = fb.criteria.map(function (c) {
        const pct = c.maxMarks ? Math.round(c.awarded / c.maxMarks * 100) : 0;
        const cls = c.awarded >= c.maxMarks ? 'pc-full'
            : (c.awarded > 0 ? 'pc-part' : 'pc-zero');
        const evidence = [];
        if (c.matchedEvidence.length) {
            evidence.push('<span class="pc-ev pc-ev-hit">shown: '
                + practiceCentreEscape(c.matchedEvidence.slice(0, 10).join(', ')) + '</span>');
        }
        if (c.missingEvidence.length) {
            evidence.push('<span class="pc-ev pc-ev-miss">not evidenced: '
                + practiceCentreEscape(c.missingEvidence.slice(0, 10).join(', ')) + '</span>');
        }
        return '<tr class="' + cls + '">' +
            '<td>' + practiceCentreEscape(c.label) + '</td>' +
            '<td class="pc-num">' + c.awarded + ' / ' + c.maxMarks + '</td>' +
            '<td class="pc-bar"><span style="width:' + pct + '%"></span></td>' +
            '<td class="pc-ev-cell">' + (evidence.join('<br>') || '&mdash;') + '</td>' +
            '</tr>';
    }).join('');

    const unreadableBanner = fb.unreadable
        ? '<div class="pc-warnbox"><strong>This answer could not be read.</strong> ' +
          practiceCentreEscape(fb.note) +
          '. No marks have been awarded, because guessing would misreport your performance. ' +
          'Retype the answer and submit again.</div>'
        : '';

    /* Study source. For a paper question the topic is one of two different
     * things and the screen has to say which: some questions take their
     * requirement FROM the topic, the rest are merely FILED under it while their
     * figures are composed for practice. Printing both as "Study text:" is how a
     * depreciation question ends up citing Not for Profit Organisations. */
    let source = '';
    if (fb.grounding && fb.grounding.topicId) {
        const g = fb.grounding;
        const st = fb.studySource;
        source = '<div class="pc-source"><strong>' +
            (g.aligned ? 'Requirement drawn from the study text topic:'
                        : 'Filed under this study text topic:') + '</strong> ' +
            practiceCentreEscape(g.topicTitle || g.topicId) +
            (g.chapter ? ' &mdash; ' + practiceCentreEscape(g.chapter) : '') +
            (g.aligned && st && st.studyPage
                ? ' (p. ' + practiceCentreEscape(st.studyPage) + ')' : '') +
            (g.aligned ? '' :
                '<div>The figures and facts in this question are composed for ' +
                'practice, not quoted from that topic.</div>') +
            '</div>';
    } else if (fb.studySource) {
        source = '<div class="pc-source"><strong>Study text:</strong> '
          + practiceCentreEscape(fb.studySource.title)
          + (fb.studySource.chapterTitle
              ? ' &mdash; ' + practiceCentreEscape(fb.studySource.chapterTitle) : '')
          + (fb.studySource.studyPage
              ? ' (p. ' + practiceCentreEscape(fb.studySource.studyPage) + ')' : '')
          + '</div>';
    }

    const expected = fb.expectedAnswer
        ? '<div class="pc-expected"><div class="pc-expected-title">Expected answer</div>'
          + '<div>' + practiceCentreEscape(fb.expectedAnswer.slice(0, 1200)) + '</div></div>'
        : (fb.markingNote ? ''
            : '<div class="pc-note">No expected answer could be resolved for this question.</div>');

    /* The paper's own model workings, shown after submission like any other
     * answer material. A SCENARIO paper has none and prints a marking note
     * instead of an answer, which is worth showing as the paper wrote it. */
    const workings = fb.workings
        ? '<div class="pc-expected"><div class="pc-expected-title">Model workings</div>'
          + '<div>' + practiceCentreEscape(fb.workings) + '</div></div>'
        : '';
    const markingNote = fb.markingNote
        ? '<div class="pc-note"><strong>Marking note printed with the paper:</strong> '
          + practiceCentreEscape(fb.markingNote) + '</div>'
        : '';

    const tip = fb.examTip
        ? '<div class="pc-tip"><strong>Examiner tip from the study text:</strong> '
          + practiceCentreEscape(fb.examTip) + '</div>'
        : '';

    const pct = fb.marks ? Math.round(fb.awarded / fb.marks * 100) : 0;
    const isLast = C.index >= C.questions.length - 1;

    practiceCentrePanel(practiceCentreHeader(fb.sourceLabel) +
        '<div class="pc-score" data-awarded="' + fb.awarded + '" data-marks="' + fb.marks +
        '" data-percent="' + pct + '">' +
        '<div class="pc-score-num">' + fb.awarded + '<span>/' + fb.marks + '</span></div>' +
        '<div class="pc-score-pct">' + pct + '%</div>' +
        '</div>' +
        unreadableBanner +
        '<div class="pc-question">' + practiceCentreEscape(fb.questionText) + '</div>' +
        '<table class="pc-criteria"><thead><tr><th>Criterion</th><th>Marks</th>' +
        '<th></th><th>Evidence</th></tr></thead><tbody>' + criteriaRows + '</tbody></table>' +
        expected + workings + markingNote + source + tip +
        '<div class="pc-disclaimer">' + practiceCentreEscape(fb.disclaimer) + '</div>' +
        '<div class="pc-actions">' +
        (C.index > 0 ? '<button type="button" class="pc-btn" id="pc-retry">Answer again</button>' : '') +
        (isLast
            ? '<button type="button" class="pc-btn pc-btn-primary" id="pc-finish">See session summary</button>'
            : '<button type="button" class="pc-btn pc-btn-primary" id="pc-continue">Next question</button>') +
        '</div>');

    const panel = document.querySelector('.pc-panel');
    const retry = panel.querySelector('#pc-retry');
    if (retry) {
        retry.addEventListener('click', function () {
            delete C.answers[q.id];
            practiceCentreRenderQuestion();
        });
    }
    const cont = panel.querySelector('#pc-continue');
    if (cont) {
        cont.addEventListener('click', function () {
            C.index += 1; practiceCentreRenderQuestion();
        });
    }
    const fin = panel.querySelector('#pc-finish');
    if (fin) {
        fin.addEventListener('click', function () {
            C.index = C.questions.length; practiceCentreRenderSummary();
        });
    }
}

/* ------------------------------------------------------------------ summary */

function practiceCentreRenderSummary() {
    const C = PRACTICE_CENTRE;
    // Finished and persisted exactly once per session. Re-rendering the summary
    // would otherwise re-run the totals and store the same session twice, which
    // double-counts every entry in the mistake book.
    if (!C.session.finishedAt) {
        practiceFinish(C.session);
        practiceCentrePersistSession(C.session);
    }
    const totals = C.session;
    const t = totals && totals.totals;
    if (!t) return;

    const byDiff = Object.keys(t.byDifficulty).map(function (k) {
        const b = t.byDifficulty[k];
        return '<tr><td>' + practiceCentreEscape(k) + '</td><td class="pc-num">' +
            b.awarded + ' / ' + b.marks + '</td><td class="pc-num">' + b.percent + '%</td>' +
            '<td class="pc-num">' + b.count + '</td></tr>';
    }).join('');

    const perQuestion = (totals.results || []).map(function (r, i) {
        const status = r.unreadable ? 'unreadable'
            : (r.percent >= 70 ? 'strong' : (r.percent >= 40 ? 'partial' : 'weak'));
        return '<tr class="pc-q-' + status + '"><td>' + (i + 1) + '</td>' +
            '<td>' + practiceCentreEscape(PRACTICE_CENTRE.questions[i] ? PRACTICE_CENTRE.questions[i].text : r.questionId).slice(0, 110) + '</td>' +
            '<td class="pc-num">' + r.awarded + ' / ' + r.maxMarks + '</td>' +
            '<td>' + practiceCentreEscape(status) + '</td></tr>';
    }).join('');

    const mb = practiceCentreMistakeBook();
    const mbRows = mb.entries.slice(0, 8).map(function (e) {
        return '<tr><td>' + practiceCentreEscape(e.errorType.replace(/_/g, ' ').toLowerCase()) + '</td>' +
            '<td>' + practiceCentreEscape(e.criterionId) + '</td>' +
            '<td class="pc-num">' + e.marksLost + '</td>' +
            '<td class="pc-num">' + e.questionCount + '</td></tr>';
    }).join('');

    const unreadableNote = t.unreadable
        ? '<div class="pc-warnbox">' + t.unreadable + ' answer(s) could not be transcribed ' +
          'and scored zero. Those marks say nothing about your knowledge - retype them.</div>'
        : '';

    /* Which paper this was, and what part of it could be sat. The denominator of
     * this score is the written section; saying so is the difference between an
     * honest mark and one that looks 10 marks short for no stated reason. */
    const paper = C.session.paperId ? practicePaperById(C.session.paperId) : null;
    const paperNote = paper
        ? '<div class="pc-note"><strong>' + practiceCentreEscape(paper.paperId) +
          '</strong> &mdash; ' + paper.writtenMarks + ' written marks sat' +
          (paper.sectionA && !paper.sectionA.itemsAvailable
              ? ', plus ' + paper.sectionA.marks +
                ' marks of Section A that this build cannot serve (the item text was ' +
                'not recoverable, and it was not invented)'
              : '') + '.</div>'
        : '';

    practiceCentrePanel(practiceCentreHeader('Session complete') +
        '<div class="pc-score"><div class="pc-score-num">' + t.awarded +
        '<span>/' + t.marks + '</span></div><div class="pc-score-pct">' + t.percent + '%</div></div>' +
        unreadableNote + paperNote +
        (byDiff ? '<h4 class="pc-h">By difficulty</h4><table class="pc-criteria"><tbody>' +
            byDiff + '</tbody></table>' : '') +
        (mbRows ? '<h4 class="pc-h">Where marks were lost</h4><table class="pc-criteria"><tbody>' +
            mbRows + '</tbody></table>' : '') +
        '<h4 class="pc-h">Every question</h4><table class="pc-criteria"><tbody>' +
        perQuestion + '</tbody></table>' +
        '<div class="pc-disclaimer">This mark is an automated estimate from the evidence in ' +
        'your answer, for self-study. It is not an official ICAP result.</div>' +
        '<div class="pc-actions">' +
        '  <button type="button" class="pc-btn" id="pc-again">New session</button>' +
        '  <button type="button" class="pc-btn" id="pc-mistakes">Mistake book</button>' +
        '</div>');

    const panel = document.querySelector('.pc-panel');
    panel.querySelector('#pc-again').addEventListener('click', practiceCentreRenderSetup);
    panel.querySelector('#pc-mistakes').addEventListener('click', practiceCentreRenderMistakeBook);
}

/* One reader for the local session cache, used by both the mistake book and the
 * weakness screen so the two can never disagree about what has been attempted.
 * It is a cache, not a store: nothing in the marking depends on it. */
function practiceCentreLoadSessions() {
    try {
        const raw = localStorage.getItem('pc_sessions');
        if (!raw) return [];
        const all = JSON.parse(raw);
        if (!Array.isArray(all)) return [];
        return all.filter(function (s) { return s && (s.results || []).length; });
    } catch (e) {
        return [];
    }
}

function practiceCentreMistakeBook() {
    const all = practiceCentreLoadSessions();
    if (!all.length) return {};
    return practiceMistakeBook(all);
}

function practiceCentreRenderMistakeBook() {
    const mb = practiceCentreMistakeBook();
    if (!mb.entries || !mb.entries.length) {
        practiceCentrePanel(practiceCentreHeader('Mistake book') +
            '<p class="pc-note">No marks have been lost yet. Complete a session and the ' +
            'patterns will appear here.</p>');
        return;
    }
    const rows = mb.entries.map(function (e) {
        return '<tr><td>' + practiceCentreEscape(e.errorType.replace(/_/g, ' ').toLowerCase()) + '</td>' +
            '<td>' + practiceCentreEscape(e.criterionId) + '</td>' +
            '<td class="pc-num">' + e.marksLost + '</td>' +
            '<td class="pc-num">' + e.occurrences + '</td></tr>';
    }).join('');
    practiceCentrePanel(practiceCentreHeader('Mistake book') +
        '<p class="pc-note">' + mb.entries.length + ' pattern(s) across your sessions.</p>' +
        '<table class="pc-criteria"><thead><tr><th>Error</th><th>Criterion</th>' +
        '<th>Marks lost</th><th>Times</th></tr></thead><tbody>' + rows + '</tbody></table>' +
        '<div class="pc-actions"><button type="button" class="pc-btn" id="pc-back">Back</button></div>');
    document.querySelector('.pc-panel').querySelector('#pc-back')
        .addEventListener('click', practiceCentreRenderSetup);
}

/* ------------------------------------------------------ weakness screen
 * Phase 15's screen. Every number on it comes from `practiceWeaknessReport`,
 * so this function only renders: it counts nothing, judges nothing and
 * recommends nothing of its own. The one judgement it does make visible is the
 * evidence rule - a topic under three attempts reads "Not enough evidence"
 * rather than a colour, because a verdict built on one answer would send the
 * candidate to revise the wrong thing. */
function practiceCentreRenderWeakness() {
    const bank = practiceIndexBank();
    const sessions = practiceCentreLoadSessions();

    function subjectName(id) {
        const s = practiceCentreSubjectFor(id);
        return s ? s.label : id;
    }
    function topicName(id) {
        const t = practiceStudyTopic(id);
        if (!t) return id;
        return t.title + (t.chapterTitle ? ' - ' + t.chapterTitle : '');
    }
    function badge(verdict) {
        const cls = verdict === 'WEAK' ? 'pc-v-weak'
            : verdict === 'DEVELOPING' ? 'pc-v-dev'
            : verdict === 'STRONG' ? 'pc-v-strong' : 'pc-v-none';
        const label = verdict === 'INSUFFICIENT_EVIDENCE' ? 'Not enough evidence' : verdict;
        return '<span class="pc-badge ' + cls + '">' + practiceCentreEscape(label) + '</span>';
    }

    const report = practiceWeaknessReport(sessions, bank, { subjectLabel: subjectName });

    if (!report.attempted) {
        practiceCentrePanel(practiceCentreHeader('Where am I weak?') +
            '<p class="pc-note">Nothing has been marked yet. Answer a few questions first and ' +
            'this will show which subjects, topics and question types are costing marks, with ' +
            'what to do about each one.</p>' +
            '<div class="pc-actions"><button type="button" class="pc-btn" id="pc-back">' +
            'Back</button></div>');
        document.querySelector('.pc-panel').querySelector('#pc-back')
            .addEventListener('click', practiceCentreRenderSetup);
        return;
    }

    const subjRows = report.subjects.map(function (s) {
        return '<tr><td>' + practiceCentreEscape(subjectName(s.id)) + '</td>' +
            '<td class="pc-num">' + s.unique + '</td>' +
            '<td class="pc-num">' + s.awarded + '/' + s.possible + '</td>' +
            '<td class="pc-num">' + s.percent + '%</td>' +
            '<td>' + badge(s.verdict) + '</td></tr>';
    }).join('');

    const chapterRows = report.chapters.slice(0, 10).map(function (c) {
        return '<tr><td>' + practiceCentreEscape(c.title) + '</td>' +
            '<td class="pc-num">' + c.unique + '</td>' +
            '<td class="pc-num">' + c.awarded + '/' + c.possible + '</td>' +
            '<td class="pc-num">' + c.percent + '%</td>' +
            '<td>' + badge(c.verdict) + '</td></tr>';
    }).join('');

    const topicRows = report.topics.slice(0, 8).map(function (t) {
        return '<tr><td>' + practiceCentreEscape(topicName(t.id)) + '</td>' +
            '<td class="pc-num">' + t.unique + '</td>' +
            '<td class="pc-num">' + t.percent + '%</td>' +
            '<td class="pc-num">' + t.marksLost + '</td>' +
            '<td>' + badge(t.verdict) + '</td></tr>';
    }).join('');

    const typeRows = report.types.map(function (t) {
        return '<tr><td>' + practiceCentreEscape(String(t.id).toLowerCase()) + '</td>' +
            '<td class="pc-num">' + t.unique + '</td>' +
            '<td class="pc-num">' + t.percent + '%</td>' +
            '<td>' + badge(t.verdict) + '</td></tr>';
    }).join('');

    const errRows = report.errors.slice(0, 8).map(function (e) {
        return '<tr><td>' + practiceCentreEscape(
            String(e.errorType).replace(/_/g, ' ').toLowerCase()) + '</td>' +
            '<td class="pc-num">' + e.marksLost + '</td>' +
            '<td class="pc-num">' + e.occurrences + '</td>' +
            '<td>' + practiceCentreEscape(e.hint) + '</td></tr>';
    }).join('');

    const recHtml = report.recommendations.length
        ? report.recommendations.map(function (r) {
            let action = '';
            if (r.kind === 'STUDY') {
                action = ' <button type="button" class="pc-btn" data-pc-rec="topic" data-pc-id="' +
                    practiceCentreEscape(r.topicId) + '">Open the topic</button>';
            } else if (r.kind === 'PRACTICE') {
                action = ' <button type="button" class="pc-btn" data-pc-rec="type" data-pc-id="' +
                    practiceCentreEscape(r.type) + '">Start 5 questions</button>';
            } else if (r.kind === 'PAPER') {
                action = ' <button type="button" class="pc-btn" data-pc-rec="paper" data-pc-id="' +
                    practiceCentreEscape(r.paperId) + '">Open the paper</button>';
            } else if (r.kind === 'MORE_ATTEMPTS') {
                action = ' <button type="button" class="pc-btn" data-pc-rec="more" data-pc-id="' +
                    practiceCentreEscape(r.chapterId) + '">Answer what is left</button>';
            }
            return '<div class="pc-rec"><strong>' + r.rank + '. '
                + practiceCentreEscape({ STUDY: 'Revise', PRACTICE: 'Drill', PAPER: 'Paper',
                    MORE_ATTEMPTS: 'More evidence', TECHNIQUE: 'Technique' }[r.kind] || r.kind)
                + '</strong><br>' + practiceCentreEscape(r.text) + action + '</div>';
        }).join('')
        : '<p class="pc-note">Nothing has cost enough marks yet to point at. Keep going.</p>';

    practiceCentrePanel(practiceCentreHeader('Where am I weak?') +
        '<div class="pc-score"><div class="pc-score-num">' + report.awarded +
        '<span>/' + report.possible + '</span></div>' +
        '<div class="pc-score-pct">' + report.percent + '%</div></div>' +
        '<p class="pc-note">' + report.attempted + ' question(s) across ' + report.sessions +
        ' session(s).' + (report.objectiveAttempts
            ? ' ' + report.objectiveAttempts +
              ' of them were objective items, marked on the examiner\'s own letters with no partial credit.'
            : '') + '</p>' +
        (report.unreadable
            ? '<div class="pc-warnbox"><strong>' + report.unreadable +
              ' answer(s) could not be read</strong> and are counted as zero. Retype and ' +
              'resubmit them before reading the rest of this report - the weakness below ' +
              'may be a reading failure rather than a knowledge one.</div>'
            : '') +
        '<div class="pc-h">By subject</div>' +
        '<table class="pc-criteria"><thead><tr><th>Subject</th><th>Questions</th>' +
        '<th>Marks</th><th>Score</th><th>Verdict</th></tr></thead><tbody>' +
        subjRows + '</tbody></table>' +
        '<div class="pc-h">Chapters, worst first - verdicts are made here</div>' +
        '<table class="pc-criteria"><thead><tr><th>Chapter</th><th>Questions</th>' +
        '<th>Marks</th><th>Score</th><th>Verdict</th></tr></thead><tbody>' +
        chapterRows + '</tbody></table>' +
        '<div class="pc-h">Topics, worst first</div>' +
        '<table class="pc-criteria"><thead><tr><th>Topic</th><th>Questions</th>' +
        '<th>Score</th><th>Marks lost</th><th>Verdict</th></tr></thead><tbody>' +
        topicRows + '</tbody></table>' +
        '<div class="pc-h">By question type</div>' +
        '<table class="pc-criteria"><thead><tr><th>Type</th><th>Questions</th>' +
        '<th>Score</th><th>Verdict</th></tr></thead><tbody>' + typeRows + '</tbody></table>' +
        '<p class="pc-note">Verdicts are made on chapters because this bank files ' +
        'one generated question per topic: one answer cannot decide a topic. So ' +
        report.insufficient.length + ' chapter(s) and ' + report.insufficientTopics +
        ' topic(s) still read "Not enough evidence" instead of weak - which is the ' +
        'truth, not a gap in the report.</p>' +
        '<div class="pc-h">Where the marks went</div>' +
        '<table class="pc-criteria"><thead><tr><th>What happened</th><th>Marks lost</th>' +
        '<th>Times</th><th>What to do</th></tr></thead><tbody>' + errRows + '</tbody></table>' +
        '<div class="pc-h">What to do next</div>' + recHtml +
        '<div class="pc-actions"><button type="button" class="pc-btn" id="pc-back">Back</button></div>');

    const panel = document.querySelector('.pc-panel');
    panel.querySelector('#pc-back').addEventListener('click', practiceCentreRenderSetup);
    Array.prototype.forEach.call(panel.querySelectorAll('[data-pc-rec]'), function (btn) {
        btn.addEventListener('click', function () {
            const act = btn.getAttribute('data-pc-rec');
            const id = btn.getAttribute('data-pc-id');
            if (act === 'topic') {
                // Out of the overlay first: the topic modal sits below it.
                practiceCentreClose();
                if (typeof openTopicModal === 'function') openTopicModal(id);
            } else if (act === 'type') {
                practiceCentreStartSession({
                    kind: 'GENERATED_PRACTICE', type: id, count: 5
                });
            } else if (act === 'paper') {
                practiceCentreRenderPaperOverview(id);
            } else if (act === 'more') {
                const done = {};
                sessions.forEach(function (s) {
                    (s.results || []).forEach(function (r) { done[r.questionId] = 1; });
                });
                const chapIndex = practiceChapterIndex();
                const qs = (bank.all || []).filter(function (q) {
                    const ch = q.topicId ? chapIndex[q.topicId] : null;
                    return ch && ch.key === id && !done[q.id]
                        && q.kind === 'GENERATED_PRACTICE';
                });
                if (!qs.length) {
                    practiceCentrePanel(practiceCentreHeader('Nothing left to answer') +
                        '<p class="pc-note">Every practice question in that chapter has ' +
                        'been answered already. Revise it from the study text, then come ' +
                        'back and take it again.</p>' +
                        '<div class="pc-actions"><button type="button" class="pc-btn" ' +
                        'id="pc-back">Back</button></div>');
                    document.querySelector('.pc-panel').querySelector('#pc-back')
                        .addEventListener('click', practiceCentreRenderWeakness);
                    return;
                }
                practiceCentreStartSession({
                    kind: 'GENERATED_PRACTICE',
                    questions: qs.slice(0, 5),
                    subjectId: qs[0].subjectId
                });
            }
        });
    });
}

/* ------------------------------------------------------- analytics screen
 * Phase 16. Every number comes from `practiceAnalyticsReport`; this only
 * renders it. The screen reports what has happened - volume, reach, mix,
 * direction - and never what will happen: there is no projection here, and
 * where the history cannot support a statement the empty wording is printed
 * instead of a guess. */
function practiceCentreRenderAnalytics() {
    const bank = practiceIndexBank();
    const report = practiceAnalyticsReport(practiceCentreLoadSessions(), bank);

    function subjectName(id) {
        const s = practiceCentreSubjectFor(id);
        return s ? s.label : id;
    }
    function bar(pct) {
        const w = Math.max(0, Math.min(100, Number(pct) || 0));
        return '<span class="pc-bar"><span style="width:' + w + '%"></span></span>';
    }
    function back() {
        return '<div class="pc-actions"><button type="button" class="pc-btn" id="pc-back">' +
            'Back</button></div>';
    }

    if (!report.attempted) {
        practiceCentrePanel(practiceCentreHeader('Progress &amp; analytics') +
            '<p class="pc-note">Nothing has been marked yet, so there is nothing to ' +
            'report. This screen will show how much of the bank you have reached, where ' +
            'your marks came from and how your scores are moving - once there are scores.</p>' +
            back());
        document.querySelector('.pc-panel').querySelector('#pc-back')
            .addEventListener('click', practiceCentreRenderSetup);
        return;
    }

    /* ---- direction ------------------------------------------------------ */
    let trendHtml;
    if (!report.trend.enough) {
        trendHtml = '<p class="pc-note">Fewer than two finished sittings carry marks, ' +
            'so no direction can honestly be stated yet. Two is the minimum, and even ' +
            'then a movement of under ' + PRACTICE_ANALYTICS_FLAT_POINTS +
            ' points is reported below as no clear change.</p>';
    } else {
        const words = { UP: 'moving up', DOWN: 'slipping', FLAT: 'showing no clear change' };
        trendHtml = '<p class="pc-note">Your more recent sittings average ' +
            report.trend.secondHalf + '% against ' + report.trend.firstHalf +
            '% for your earlier ones - ' + report.trend.delta + ' points, which is ' +
            (words[report.trend.direction] || 'not stated') + '. ' +
            'Movements under ' + PRACTICE_ANALYTICS_FLAT_POINTS +
            ' points are reported as no clear change rather than as progress.</p>';
        if (report.trend.best && report.trend.worst) {
            trendHtml += '<p class="pc-note">Best sitting: ' +
                practiceCentreEscape(String(report.trend.best.date || '').slice(0, 10)) +
                ' at ' + report.trend.best.percent + '%. Weakest: ' +
                practiceCentreEscape(String(report.trend.worst.date || '').slice(0, 10)) +
                ' at ' + report.trend.worst.percent + '%.</p>';
        }
    }
    const trendRows = report.trend.points.slice(-12).map(function (p) {
        return '<tr><td>' + practiceCentreEscape(String(p.date || 'undated').slice(0, 10)) +
            '</td><td>' + practiceCentreEscape((p.label || '').slice(0, 46)) + '</td>' +
            '<td class="pc-num">' + p.questions + '</td>' +
            '<td class="pc-num">' + p.awarded + '/' + p.marks + '</td>' +
            '<td class="pc-num">' + p.percent + '%</td><td>' + bar(p.percent) + '</td></tr>';
    }).join('');

    /* ---- coverage ------------------------------------------------------- */
    const covRows = report.coverage.subjects.map(function (s) {
        return '<tr><td>' + practiceCentreEscape(subjectName(s.subjectId)) + '</td>' +
            '<td class="pc-num">' + s.reached + '</td>' +
            '<td class="pc-num">' + s.available + '</td>' +
            '<td class="pc-num">' + s.percent + '%</td><td>' + bar(s.percent) + '</td></tr>';
    }).join('');
    const untouched = report.coverage.untouchedSubjects.length
        ? '<p class="pc-note">Not opened at all yet: ' +
          practiceCentreEscape(report.coverage.untouchedSubjects.map(subjectName).join(', ')) +
          '.</p>'
        : '<p class="pc-note">Every subject has been opened at least once.</p>';

    /* ---- mix ------------------------------------------------------------ */
    const srcRows = report.bySource.map(function (m) {
        return '<tr><td>' + practiceCentreEscape(String(m.id).toLowerCase()) + '</td>' +
            '<td class="pc-num">' + m.count + '</td>' +
            '<td class="pc-num">' + m.awarded + '/' + m.possible + '</td>' +
            '<td class="pc-num">' + m.percent + '%</td></tr>';
    }).join('');
    const diffRows = report.byDifficulty.map(function (m) {
        return '<tr><td>' + practiceCentreEscape(String(m.id).toLowerCase()) + '</td>' +
            '<td class="pc-num">' + m.count + '</td>' +
            '<td class="pc-num">' + m.percent + '%</td></tr>';
    }).join('');

    /* ---- time ----------------------------------------------------------- */
    let timeHtml;
    if (report.time.measured) {
        timeHtml = '<p class="pc-note">' + report.time.avgPerSession +
            ' minutes a sitting on average, ' + report.time.avgPerQuestion +
            ' minutes a question, over ' + report.time.measured + ' sitting(s).</p>';
    } else {
        timeHtml = '<p class="pc-note">No usable timing data yet.</p>';
    }
    if (report.time.ignored || report.time.unmeasured) {
        timeHtml += '<p class="pc-note">' + report.time.ignored +
            ' sitting(s) had a clock that could not be trusted and ' +
            report.time.unmeasured + ' had no timestamps at all; both were left out ' +
            'of these averages instead of being averaged in.</p>';
    }

    practiceCentrePanel(practiceCentreHeader('Progress &amp; analytics') +
        '<div class="pc-score"><div class="pc-score-num">' + report.awarded +
        '<span>/' + report.possible + '</span></div>' +
        '<div class="pc-score-pct">' + report.percent + '%</div></div>' +
        '<p class="pc-note">' + report.sessions + ' session(s), ' + report.attempted +
        ' question(s), ' + report.daysActive + ' day(s) of practice' +
        (report.lastActivity ? ', last on ' +
            practiceCentreEscape(String(report.lastActivity).slice(0, 10)) : '') +
        '. History covers your last ' + report.historyLimit + ' sessions.</p>' +

        '<div class="pc-h">Direction</div>' + trendHtml +
        '<table class="pc-criteria"><thead><tr><th>Date</th><th>Sitting</th>' +
        '<th>Questions</th><th>Marks</th><th>Score</th><th></th></tr></thead><tbody>' +
        trendRows + '</tbody></table>' +

        '<div class="pc-h">Coverage of the question bank</div>' +
        '<p class="pc-note">' + report.coverage.reached + ' of ' +
        report.coverage.total + ' questions reached (' + report.coverage.percent +
        '%), across ' + report.coverage.chaptersReached + ' of ' +
        report.coverage.chaptersTotal + ' chapters.</p>' +
        '<table class="pc-criteria"><thead><tr><th>Subject</th><th>Reached</th>' +
        '<th>Available</th><th>Covered</th><th></th></tr></thead><tbody>' +
        covRows + '</tbody></table>' + untouched +

        '<div class="pc-h">Where the marks came from</div>' +
        '<table class="pc-criteria"><thead><tr><th>Source</th><th>Questions</th>' +
        '<th>Marks</th><th>Score</th></tr></thead><tbody>' + srcRows + '</tbody></table>' +
        '<table class="pc-criteria"><thead><tr><th>Difficulty</th><th>Questions</th>' +
        '<th>Score</th></tr></thead><tbody>' + diffRows + '</tbody></table>' +
        '<p class="pc-note">Difficulty is set on generated questions; official ' +
        'past-paper questions carry none of their own and so read "unset". Read the ' +
        'two together: a score that holds across ICAP material and practice material ' +
        'alike means more than either alone.</p>' +

        '<div class="pc-h">Objective against written</div>' +
        '<table class="pc-criteria"><thead><tr><th>Kind</th><th>Questions</th>' +
        '<th>Marks</th><th>Score</th></tr></thead><tbody>' +
        '<tr><td>objective</td><td class="pc-num">' + report.objective.count +
        '</td><td class="pc-num">' + report.objective.awarded + '/' +
        report.objective.possible + '</td><td class="pc-num">' +
        report.objective.percent + '%</td></tr>' +
        '<tr><td>written</td><td class="pc-num">' + report.written.count +
        '</td><td class="pc-num">' + report.written.awarded + '/' +
        report.written.possible + '</td><td class="pc-num">' +
        report.written.percent + '%</td></tr>' +
        '</tbody></table>' +
        '<p class="pc-note">These two are not comparable and are never ranked ' +
        'against each other: objective items are marked on the examiner\'s own ' +
        'letters with no partial credit, so a lower rate there is a different ' +
        'measurement, not a worse one.</p>' +

        '<div class="pc-h">Data quality</div>' +
        '<p class="pc-note">' + report.unreadable + ' answer(s) (' +
        report.unreadableRate + '%) could not be read and scored zero; ' +
        report.transcribed + ' answer(s) were transcribed and ' + report.typed +
        ' were typed by hand, with ' + report.lowConfidence +
        ' read below the confidence floor. Typed answers are counted as evidence ' +
        'all the same - this split records where the text came from, not how good it is.</p>' +

        '<div class="pc-h">Time</div>' + timeHtml +
        back());

    document.querySelector('.pc-panel').querySelector('#pc-back')
        .addEventListener('click', practiceCentreRenderSetup);
}

/* ------------------------------------------------------- content review
 * Phase 17. Everything shown here comes from either the build-time register
 * (`REVIEW_REGISTER`, produced by build_review_register.py against the same
 * sources the bank came from) or `practiceReviewReport()`, which re-runs what
 * it can over the bank as loaded in this page. The two are shown side by side
 * so an approval decision is made against both what was built and what a
 * candidate actually sits. A static page has no server and no roles: this
 * screen says so, and exports its decisions as a file the school keeps. */
function practiceCentreRenderReview() {
    const bank = practiceIndexBank();
    const profile = (typeof getProfile === 'function') ? getProfile() : null;
    const registry = (typeof REVIEW_REGISTER !== 'undefined') ? REVIEW_REGISTER : null;
    const report = (typeof practiceReviewReport === 'function')
        ? practiceReviewReport(bank, registry) : null;

    function esc(s) {
        return practiceCentreEscape(String(s === null || s === undefined ? '' : s));
    }
    function back() {
        return '<div class="pc-actions"><button type="button" class="pc-btn" id="pc-back">' +
            'Back</button></div>';
    }
    function tableHtml(head, rows) {
        return '<table class="pc-criteria"><thead><tr>' + head +
            '</tr></thead><tbody>' + rows + '</tbody></table>';
    }
    function th(t) { return '<th>' + t + '</th>'; }

    if (!report || !registry) {
        practiceCentrePanel(practiceCentreHeader('Content review &amp; approval') +
            '<p class="pc-note">The review report or the build-time register is ' +
            'missing from this build, so there is nothing to review here. That is ' +
            'a build problem, not a content problem.</p>' + back());
        document.querySelector('.pc-panel').querySelector('#pc-back')
            .addEventListener('click', practiceCentreRenderSetup);
        return;
    }

    const digest = String(report.digest || 'unknown');
    const reviewer = (profile && (profile.name || profile.email)) || 'Signed-in user';
    const reviewerLine = (profile && profile.email)
        ? reviewer + ' (' + profile.email + ')' : reviewer;
    const REVIEW_KEY = 'pc_review';
    let decisions = [];
    try {
        const raw = localStorage.getItem(REVIEW_KEY);
        decisions = raw ? JSON.parse(raw) : [];
        if (!Array.isArray(decisions)) decisions = [];
    } catch (e) { decisions = []; }

    const current = decisions
        .filter(function (d) { return String(d.digest) === digest; })
        .sort(function (a, b) {
            return String(b.at || '').localeCompare(String(a.at || ''));
        })[0] || null;
    let statusHtml = '<p class="pc-note">Sign-off for this content state: <span class="' +
        (current ? (current.decision === 'APPROVED' ? 'pc-status-ok'
            : (current.decision === 'REJECTED' ? 'pc-status-fail' : 'pc-status-note'))
            : 'pc-status-note') + '">' + esc(current ? current.decision : 'NOT REVIEWED') +
        '</span>' + (current
            ? ' by ' + esc(current.reviewer) + ' on ' +
              esc(String(current.at || '').slice(0, 16))
            : '') + '.</p>';
    if (current && current.note) {
        statusHtml += '<p class="pc-note">Note: ' + esc(current.note) + '</p>';
    }
    if (!current) {
        statusHtml += '<p class="pc-note">No decision has been recorded for this ' +
            'digest. Nothing here blocks a candidate either way - this record is ' +
            'the school\'s own check that content was reviewed before it was ' +
            'relied on.</p>';
    }

    const c = report.counts || {};
    const digestLine = '<p class="pc-note">' + c.questions + ' questions in this ' +
        'build (' + c.generated + ' generated, ' + c.official + ' official ' +
        'past-paper, ' + c.paperQuestions + ' in generated papers across ' +
        c.papers + ' papers), ' + c.subjects + ' subjects, ' + c.chapters +
        ' chapters. Register built at ' + esc(report.builtAt || registry.builtAt) +
        '; content digest ' + esc(digest) + '.</p>';

    const liveRows = report.checks.map(function (chk) {
        const cls = chk.status === 'PASS' ? 'pc-status-ok' : 'pc-status-fail';
        return '<tr><td>' + esc(chk.name) + '</td>' +
            '<td><div class="pc-sub">' + esc(chk.purpose) + '</div></td>' +
            '<td class="pc-num">' + chk.checked + '</td>' +
            '<td class="pc-num">' + chk.failed + '</td>' +
            '<td><span class="' + cls + '">' + esc(chk.status) + '</span></td></tr>';
    }).join('');
    const failing = report.checks.filter(function (chk) { return chk.failed > 0; });
    let failingHtml = '';
    if (failing.length) {
        failingHtml = '<div class="pc-h">Items behind a failing check</div>' +
            failing.map(function (chk) {
                return '<p class="pc-note"><strong>' + esc(chk.name) + '</strong>: ' +
                    chk.failures.map(function (f) {
                        return esc(f.id) + (f.why ? ' - ' + esc(f.why) : '');
                    }).join('; ') + '.</p>';
            }).join('');
    }

    const regRows = registry.checks.map(function (chk) {
        const enforced = chk.group === 'ENFORCED';
        const cls = enforced ? (chk.ok ? 'pc-status-ok' : 'pc-status-fail')
            : 'pc-status-note';
        const statusText = enforced ? (chk.ok ? 'PASS' : 'FAIL') : 'reported';
        const measured = (typeof chk.measured === 'object' && chk.measured !== null)
            ? JSON.stringify(chk.measured) : String(chk.measured);
        return '<tr><td>' + esc(chk.name) + '</td>' +
            '<td><div class="pc-sub">' + esc(chk.purpose) + '</div>' +
            esc(chk.source) + '</td>' +
            '<td class="pc-num">' + esc(measured) + '</td>' +
            '<td><span class="' + cls + '">' + statusText + '</span></td></tr>';
    }).join('');
    const regDetails = registry.checks.filter(function (chk) {
        return chk.group === 'REPORTED' && chk.detail;
    }).map(function (chk) {
        const d = (typeof chk.detail === 'string') ? chk.detail
            : JSON.stringify(chk.detail);
        return '<p class="pc-note"><strong>' + esc(chk.name) + '</strong>: ' +
            esc(d) + '</p>';
    }).join('');

    const watchHtml = report.watch.map(function (w) {
        return '<p class="pc-note"><strong>' + esc(w.id) + '</strong>: ' +
            w.count + ' - ' + esc(w.why) + '</p>';
    }).join('');

    const driftRows = report.drift.map(function (d) {
        return '<tr><td>' + esc(d.label) + '</td>' +
            '<td class="pc-num">' + esc(d.registered) + '</td>' +
            '<td class="pc-num">' + esc(d.live) + '</td>' +
            '<td>' + (d.matches
                ? '<span class="pc-status-ok">same</span>'
                : '<span class="pc-status-fail">drifted</span>') + '</td></tr>';
    }).join('');

    const limitsHtml = (registry.limits || []).map(function (l) {
        return '<p class="pc-note"><strong>' + esc(l.what) + '</strong>: ' +
            esc(l.detail) + '</p>';
    }).join('');

    const histRows = decisions.slice(0, 20).map(function (d) {
        return '<tr><td>' + esc(String(d.at || '').slice(0, 16)) + '</td>' +
            '<td>' + esc(d.decision) + '</td>' +
            '<td>' + esc(d.reviewer) + '</td>' +
            '<td>' + esc(String(d.digest || '').slice(0, 24)) + '</td>' +
            '<td>' + esc(d.note || '') + '</td></tr>';
    }).join('');
    const histHtml = (decisions.length
        ? '<div class="pc-h">Decision history (this browser)</div>' +
          tableHtml(th('Date') + th('Decision') + th('Reviewer') + th('Digest') +
              th('Note'), histRows)
        : '');

    const signOff = '<div class="pc-h">Sign-off</div>' + statusHtml +
        '<p class="pc-note"><input type="text" id="pc-review-note" class="pc-input" ' +
        'maxlength="200" placeholder="Decision note (optional)"> ' +
        '<button type="button" class="pc-btn pc-btn-primary" id="pc-approve">' +
        'Approve</button> ' +
        '<button type="button" class="pc-btn" id="pc-changes">Request changes</button> ' +
        '<button type="button" class="pc-btn" id="pc-reject">Reject</button> ' +
        '<button type="button" class="pc-btn" id="pc-export">Export record (JSON)</button>' +
        '</p>' +
        '<p class="pc-note">Decisions are cached in this browser as a convenience ' +
        'and are included in the exported file. The file - with its content ' +
        'digest - is the record; a static page cannot vault it, enforce a role ' +
        'or timestamp it the way a server can.</p>';

    practiceCentrePanel(practiceCentreHeader('Content review &amp; approval') +
        '<p class="pc-note">Reviewer: <strong>' + esc(reviewerLine) + '</strong>. ' +
        'This is the school\'s own content check: what the build pipeline ' +
        'verified when the bank was built, re-checked over the bank a candidate ' +
        'actually sits. It is not a server and claims no role enforcement or ' +
        'central storage.</p>' +
        digestLine +
        '<div class="pc-h">Re-checked live, in this page</div>' +
        '<p class="pc-note">' + report.checks.length + ' checks re-run now over the ' +
        'loaded bank - the half of the register the browser can still prove. A ' +
        'check that passes now but failed at build time (or the reverse) means ' +
        'the page and the register drifted apart.</p>' +
        tableHtml(th('Check') + th('What it verifies') + th('Counted over') +
            th('Failed') + th('Status'), liveRows) +
        failingHtml +
        '<div class="pc-h">What the pipeline recorded at build time</div>' +
        '<p class="pc-note">' + registry.checks.length + ' checks ran in ' +
        'build_review_register.py over the same sources the bank came from. ' +
        'ENFORCED checks fail the build when wrong; REPORTED checks are measured ' +
        'and shown, not corrected, because the corpus itself cannot be remade ' +
        'inside the pipeline.</p>' +
        tableHtml(th('Check') + th('What it verified') + th('Measured') +
            th('Status'), regRows) +
        regDetails +
        '<div class="pc-h">Watch items</div>' +
        '<p class="pc-note">Not pass/fail: things the checks cannot fully decide, ' +
        'watched because a future corpus change could turn them into defects.</p>' +
        watchHtml +
        '<div class="pc-h">Register against the loaded bank</div>' +
        '<p class="pc-note">The same quantities as measured at build time and now. ' +
        'A mismatch here means the bank in this page is not the bank the register ' +
        'was built for.</p>' +
        tableHtml(th('Quantity') + th('At build') + th('Now') + th(''),
            driftRows) +
        '<div class="pc-h">What this build cannot do</div>' + limitsHtml +
        signOff + histHtml + back());

    const panelEl = document.querySelector('.pc-panel');
    panelEl.querySelector('#pc-back').addEventListener('click', practiceCentreRenderSetup);
    const noteInput = panelEl.querySelector('#pc-review-note');
    function record(decision) {
        return function () {
            const note = (noteInput && noteInput.value) ? noteInput.value.trim() : '';
            const entry = {
                decisionId: 'pc-d-' + Date.now() + '-' +
                    Math.floor(Math.random() * 1000),
                at: new Date().toISOString(),
                reviewer: reviewerLine,
                digest: digest,
                builtAt: report.builtAt || registry.builtAt || '',
                decision: decision,
                note: note.slice(0, 200)
            };
            decisions.unshift(entry);
            decisions = decisions.slice(0, 20);
            try {
                localStorage.setItem(REVIEW_KEY, JSON.stringify(decisions));
            } catch (e) { /* storage disabled - decision stands for this visit */ }
            practiceCentreRenderReview();
        };
    }
    const approveBtn = panelEl.querySelector('#pc-approve');
    if (approveBtn) approveBtn.addEventListener('click', record('APPROVED'));
    const changesBtn = panelEl.querySelector('#pc-changes');
    if (changesBtn) changesBtn.addEventListener('click', record('CHANGES_REQUESTED'));
    const rejectBtn = panelEl.querySelector('#pc-reject');
    if (rejectBtn) rejectBtn.addEventListener('click', record('REJECTED'));
    const exportBtn = panelEl.querySelector('#pc-export');
    if (exportBtn) {
        exportBtn.addEventListener('click', function () {
            const payload = {
                exportedAt: new Date().toISOString(),
                reviewer: reviewerLine,
                digest: digest,
                sheet: 'CAF Practice Centre content review record',
                counts: c,
                checks: registry.checks,
                liveReport: {
                    checks: report.checks,
                    watch: report.watch,
                    drift: report.drift
                },
                decisions: decisions
            };
            const blob = new Blob([JSON.stringify(payload, null, 2)],
                { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = 'content-review-' +
                String(digest).replace(/[^a-z0-9@.+_-]/gi, '_') + '.json';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        });
    }
}

/* Persist finished sessions locally so the mistake book has history. This is a
 * convenience cache only - it is not the source of truth, and nothing about the
 * marking depends on it. */
function practiceCentrePersistSession(session) {
    try {
        const raw = localStorage.getItem('pc_sessions');
        const all = raw ? JSON.parse(raw) : [];
        all.push(session);
        localStorage.setItem('pc_sessions', JSON.stringify(all.slice(-50)));
    } catch (e) { /* storage disabled - the session still works in memory */ }
}

document.addEventListener('DOMContentLoaded', function () {
    initPracticeCentre();
    document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape' && PRACTICE_CENTRE.overlayOpen) practiceCentreClose();
    });
});

